import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { CATEGORIES, MOCK_CONTENT } from '../constants';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { Filter } from 'lucide-react';

export const CategoriesPage: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const currentFilter = searchParams.get('filter') || 'all';
  const [activeCategory, setActiveCategory] = useState(currentFilter);

  useEffect(() => {
    setActiveCategory(currentFilter);
  }, [currentFilter]);

  const handleFilterChange = (slug: string) => {
    setActiveCategory(slug);
    setSearchParams({ filter: slug });
  };

  const activeCategoryLabel = activeCategory === 'all' 
    ? 'Бүх мэдлэг' 
    : CATEGORIES.find(c => c.slug === activeCategory)?.label || 'Ангилал';

  const filteredContent = activeCategory === 'all'
    ? MOCK_CONTENT
    : MOCK_CONTENT.filter(c => {
         const catObj = CATEGORIES.find(cat => cat.slug === activeCategory);
         return catObj ? c.category === catObj.label : true;
      });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8">
        <h1 className="text-3xl font-extrabold text-gray-900 mb-4 md:mb-0">
          {activeCategoryLabel}
        </h1>

        {/* Simple Sort Dropdown (Visual only) */}
        <div className="flex items-center gap-2">
            <span className="text-sm text-gray-500">Эрэмбэлэх:</span>
            <button className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm font-medium hover:bg-gray-50">
                <Filter size={16} />
                <span>Шинэ нь эхэндээ</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

        {/* Sidebar Filters */}
        <div className="lg:col-span-1">
            <div className="bg-white p-4 rounded-xl shadow-sm border border-gray-100 sticky top-24">
                <h3 className="font-bold text-gray-900 mb-4 px-2">Ангилал</h3>
                <div className="space-y-1">
                    <button
                        onClick={() => handleFilterChange('all')}
                        className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                            activeCategory === 'all' ? 'bg-primary-50 text-primary-700' : 'text-gray-600 hover:bg-gray-50'
                        }`}
                    >
                        Бүгд
                    </button>
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => handleFilterChange(cat.slug)}
                            className={`w-full text-left px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                                activeCategory === cat.slug ? 'bg-primary-50 text-primary-700' : 'text-gray-600 hover:bg-gray-50'
                            }`}
                        >
                            {cat.label}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        {/* Content Grid */}
        <div className="lg:col-span-3">
            {filteredContent.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-6">
                    {filteredContent.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
            ) : (
                <div className="py-20 text-center bg-gray-50 rounded-2xl border border-dashed border-gray-200">
                    <p className="text-gray-500">Одоогоор энэ ангилалд мэдээлэл байхгүй байна.</p>
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState } from 'react';
