import React, { useState, useEffect } from 'react';
import { useSearchParams } from 'react-router-dom';
import { CATEGORIES, MOCK_CONTENT } from '../constants';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { Filter } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';

export const CategoriesPage: React.FC = () => {
  const [searchParams, setSearchParams] = useSearchParams();
  const currentFilter = searchParams.get('filter') || 'all';
  const [activeCategory, setActiveCategory] = useState(currentFilter);
  const { t, language } = useLanguage();
  const isEn = language === 'en';

  useEffect(() => {
    setActiveCategory(currentFilter);
  }, [currentFilter]);

  const handleFilterChange = (slug: string) => {
    setActiveCategory(slug);
    setSearchParams({ filter: slug });
  };

  const activeCategoryLabel = activeCategory === 'all' 
    ? t('all_knowledge')
    : CATEGORIES.find(c => c.slug === activeCategory)?.label || t('nav_categories'); // Using MN label for title as requested for UI labels

  const filteredContent = activeCategory === 'all'
    ? MOCK_CONTENT
    : MOCK_CONTENT.filter(c => {
         const catObj = CATEGORIES.find(cat => cat.slug === activeCategory);
         // Filter logic: content has categories, we need to match carefully
         // Currently mock content category is stored as string in MN usually
         return catObj ? (c.category === catObj.label || c.category_en === catObj.label_en) : true;
      });

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8">
        <h1 className="text-3xl font-extrabold text-slate-100 mb-4 md:mb-0 drop-shadow-md">
          {activeCategoryLabel}
        </h1>

        {/* Simple Sort Dropdown (Visual only) */}
        <div className="flex items-center gap-3">
            <span className="text-sm text-slate-500 font-medium">{t('sort_by')}</span>
            <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-white/10 rounded-lg text-sm font-medium hover:bg-white/5 text-slate-300 transition-colors">
                <Filter size={16} />
                <span>{t('newest')}</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

        {/* Sidebar Filters */}
        <div className="lg:col-span-1">
            <div className="bg-surface p-4 rounded-xl shadow-lg border border-white/5 sticky top-24">
                <h3 className="font-bold text-slate-200 mb-4 px-2">{t('nav_categories')}</h3>
                <div className="space-y-1">
                    <button
                        onClick={() => handleFilterChange('all')}
                        className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                            activeCategory === 'all' 
                            ? 'bg-primary-900/30 text-primary-400 border border-primary-500/20 shadow-glow' 
                            : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'
                        }`}
                    >
                        {t('all_knowledge')}
                    </button>
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => handleFilterChange(cat.slug)}
                            className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                                activeCategory === cat.slug 
                                ? 'bg-primary-900/30 text-primary-400 border border-primary-500/20 shadow-glow' 
                                : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'
                            }`}
                        >
                            {cat.label}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        {/* Content Grid */}
        <div className="lg:col-span-3">
            {filteredContent.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-8">
                    {filteredContent.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
            ) : (
                <div className="py-20 text-center bg-surface rounded-xl border border-dashed border-white/10">
                    <p className="text-slate-500">{t('no_results')}</p>
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search as SearchIcon } from 'lucide-react';
import { MOCK_CONTENT } from '../constants';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { useSearchParams } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [searchTerm, setSearchTerm] = useState(query);
  const { t, language } = useLanguage();
  const isEn = language === 'en';

  useEffect(() => {
    setSearchTerm(query);
  }, [query]);

  const filtered = searchTerm 
    ? MOCK_CONTENT.filter(c => {
        const title = isEn ? c.title_en : c.title;
        const desc = isEn ? c.description_en : c.description;
        return title.toLowerCase().includes(searchTerm.toLowerCase()) || 
               desc.toLowerCase().includes(searchTerm.toLowerCase());
      })
    : [];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 min-h-[60vh]">
        <div className="max-w-2xl mx-auto mb-16">
            <h1 className="text-3xl font-bold text-center text-slate-100 mb-8 drop-shadow-md">{t('search_placeholder')}</h1>
            <div className="relative group">
                <input
                    type="text"
                    placeholder={t('search_placeholder')}
                    className="w-full pl-14 pr-6 py-4 rounded-2xl border border-white/10 bg-surface focus:border-primary-500 focus:ring-4 focus:ring-primary-500/20 outline-none text-lg text-slate-200 placeholder-slate-500 shadow-lg transition-all"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    autoFocus
                />
                <SearchIcon className="absolute left-5 top-1/2 transform -translate-y-1/2 text-slate-500 group-focus-within:text-primary-400 transition-colors" size={24} />
            </div>
        </div>

        {searchTerm && (
            <div>
                <h2 className="text-lg font-bold text-slate-200 mb-8 pb-4 border-b border-white/10">
                    {t('search_results')} <span className="text-primary-400 ml-2">{filtered.length}</span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {filtered.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
                {filtered.length === 0 && (
                    <div className="text-center py-16 bg-surface rounded-2xl border border-dashed border-white/10">
                         <p className="text-slate-500 text-lg">{t('no_results')}</p>
                    </div>
                )}
            </div>
        )}

        {!searchTerm && (
            <div className="text-center">
                 <p className="text-slate-600 text-sm">Channel Mongolia</p>
            </div>
