  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchValue.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchValue)}`);
      setIsOpen(false);
    }
  };

  const navLinks = [
    { label: t('nav_home'), path: '/' },
    { label: t('nav_categories'), path: '/categories' },
    { label: t('nav_about'), path: '/about' },
