          <div className="flex items-center gap-8">
            <Link to="/" className="flex items-center gap-2 group relative">
              <span className="font-bold text-xl md:text-2xl text-primary-600 dark:text-primary-400 tracking-wide group-hover:text-primary-700 dark:group-hover:text-primary-300 transition-colors dark:drop-shadow-[0_0_8px_rgba(59,130,246,0.3)]">
                Channel Mongolia
              </span>
            </Link>

            {/* Desktop Navigation */}
            <div className="hidden md:flex items-center space-x-6">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  className={`text-sm font-medium transition-all duration-200 relative ${
                    isActive(link.path)
                      ? 'text-primary-600 dark:text-primary-400 dark:drop-shadow-[0_0_5px_rgba(59,130,246,0.5)]'
                      : 'text-gray-600 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400'
                  }`}
                >
                  {link.label}
                  {isActive(link.path) && (
                    <span className="absolute -bottom-5 left-0 w-full h-0.5 bg-primary-600 dark:bg-primary-500 shadow-sm dark:shadow-[0_0_8px_#3b82f6]"></span>
                  )}
                </Link>
              ))}
            </div>
          </div>

          {/* Center: Search Bar (Desktop) */}
          <div className="hidden md:flex flex-1 max-w-lg mx-4">
             <form onSubmit={handleSearch} className="w-full relative group">
                <input 
                  type="text" 
                  value={searchValue}
                  onChange={(e) => setSearchValue(e.target.value)}
                  placeholder={t('search_placeholder')}
                  className="w-full pl-10 pr-4 py-2 rounded-full bg-gray-100 dark:bg-[#151E32]/50 border border-transparent dark:border-white/10 text-gray-900 dark:text-slate-200 placeholder-gray-500 dark:placeholder-slate-500 focus:ring-2 focus:ring-primary-500/30 focus:border-primary-500/50 outline-none transition-all group-hover:bg-white dark:group-hover:bg-[#151E32]/80 group-hover:shadow-sm"
                />
                <Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-500 dark:text-slate-500 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors" />
             </form>
          </div>

          {/* Right: Language, Theme & Actions */}
          <div className="flex items-center gap-3 md:gap-4">

            {/* Theme Toggle */}
            <button
              onClick={toggleTheme}
              className="p-2 rounded-full text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-primary-600 dark:hover:text-primary-400 transition-colors"
              title={theme === 'dark' ? t('theme_light') : t('theme_dark')}
            >
              {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
            </button>

            {/* Language Toggle */}
            <button 
               onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
               className="flex items-center gap-1 text-xs font-bold px-2 py-1 rounded transition-colors"
            >
               <span className={language === 'mn' ? 'text-primary-600 dark:text-primary-400' : 'text-gray-400 dark:text-slate-500'}>MN</span>
               <span className="text-gray-300 dark:text-slate-600">|</span>
               <span className={language === 'en' ? 'text-primary-600 dark:text-primary-400' : 'text-gray-400 dark:text-slate-500'}>EN</span>
            </button>

            <button className="hidden md:flex items-center gap-2 px-5 py-2 bg-primary-600 text-white rounded-full text-sm font-medium hover:bg-primary-700 dark:hover:bg-primary-500 shadow-sm dark:shadow-glow transition-all hover:scale-105">
              <User size={16} />
              <span>{t('login')}</span>
