import React from 'react';
import { Link } from 'react-router-dom';
import { Flame, Eye, Bookmark, Clock, ArrowRight, Quote as QuoteIcon } from 'lucide-react';
import { MOCK_CONTENT, CATEGORIES, QUOTES, INTERESTING_FACTS } from '../constants';
import { useLanguage } from '../context/LanguageContext';
import { FactBox } from './FactBox';
import { ContentItem } from '../types';

export const Sidebar: React.FC = () => {
  const { t, language } = useLanguage();
  const isEn = language === 'en';

  // --- DATA PROCESSING ---
  const mostViewed = [...MOCK_CONTENT].sort((a, b) => b.views - a.views).slice(0, 5);
  const trending = MOCK_CONTENT.filter(c => c.isTrending).slice(0, 5);
  const editorsPick = MOCK_CONTENT.filter(c => c.isEditorPick).slice(0, 3);
  const latest = [...MOCK_CONTENT].sort((a, b) => new Date(b.publishedDate).getTime() - new Date(a.publishedDate).getTime()).slice(0, 4);
  const todaysQuote = QUOTES[0];
  const todaysFact = INTERESTING_FACTS[language][0];

  // --- SUB-COMPONENTS ---

  const SidebarHeader: React.FC<{ title: string; icon?: React.ReactNode }> = ({ title, icon }) => (
    <h3 className="flex items-center gap-2 font-bold text-gray-900 dark:text-slate-100 mb-4 text-sm uppercase tracking-wider border-l-2 border-primary-500 pl-3">
      {icon}
      {title}
    </h3>
  );

  const CompactContentItem: React.FC<{ item: ContentItem; rank?: number; showImage?: boolean; metaIcon?: React.ReactNode; metaText?: string }> = ({ 
    item, rank, showImage = true, metaIcon, metaText 
  }) => {
    const title = isEn ? item.title_en : item.title;

    return (
      <Link to={`/watch/${item.id}`} className="group flex gap-3 items-start p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-white/5 transition-all">
        {showImage && (
          <div className={`relative flex-shrink-0 overflow-hidden rounded-md border border-gray-200 dark:border-white/5 group-hover:border-primary-500/30 transition-colors ${rank === 1 ? 'w-24 h-16' : 'w-16 h-12'}`}>
            <img src={item.thumbnailUrl} alt={title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />
            {rank && (
               <div className="absolute top-0 left-0 w-5 h-5 bg-primary-600 flex items-center justify-center text-[10px] font-bold text-white rounded-br-md shadow-sm">
                 {rank}
               </div>
            )}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <h4 className={`font-medium text-gray-700 dark:text-slate-300 group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors leading-snug line-clamp-2 ${rank === 1 ? 'text-sm font-bold text-gray-900 dark:text-slate-100' : 'text-xs'}`}>
            {title}
          </h4>
          <div className="flex items-center gap-2 mt-1.5 text-[10px] text-gray-500 dark:text-slate-500">
             {metaIcon}
             <span>{metaText}</span>
          </div>
        </div>
      </Link>
    );
  };

  return (
    <aside className="space-y-8 sticky top-24">

      {/* BLOCK 1: MOST VIEWED */}
      <div className="bg-white dark:bg-[#151E32]/50 backdrop-blur-sm rounded-xl p-5 border border-gray-100 dark:border-white/5 shadow-sm dark:shadow-lg">
        <SidebarHeader title={t('sb_most_viewed')} icon={<Eye size={16} className="text-primary-500" />} />
        <div className="space-y-2">
          {mostViewed.map((item, idx) => (
            <CompactContentItem 
              key={item.id} 
              item={item} 
              rank={idx + 1} 
              metaIcon={<Eye size={10} />}
              metaText={`${(item.views / 1000).toFixed(1)}k ${t('views')}`}
            />
          ))}
        </div>
      </div>

      {/* BLOCK 2: TRENDING */}
      <div className="bg-white dark:bg-[#151E32]/50 backdrop-blur-sm rounded-xl p-5 border border-gray-100 dark:border-white/5 shadow-sm dark:shadow-lg relative overflow-hidden">
        {/* Subtle orange glow for trending */}
        <div className="absolute top-0 right-0 w-20 h-20 bg-orange-500/10 rounded-full blur-2xl pointer-events-none -mr-10 -mt-10"></div>
        <SidebarHeader title={t('sb_trending')} icon={<Flame size={16} className="text-orange-500" />} />
        <div className="space-y-3">
           {trending.map(item => (
              <CompactContentItem 
                key={item.id} 
                item={item} 
                metaIcon={<Clock size={10} />}
                metaText="2h ago"
              />
           ))}
        </div>
      </div>

      {/* BLOCK 3: EDITOR'S PICK */}
      <div>
         <SidebarHeader title={t('sb_editors_pick')} icon={<Bookmark size={16} className="text-teal-500 dark:text-teal-400" />} />
         <div className="space-y-4">
            {editorsPick.map(item => {
               const title = isEn ? item.title_en : item.title;
               return (
                <Link key={item.id} to={`/watch/${item.id}`} className="block group">
                  <div className="relative aspect-[16/9] rounded-lg overflow-hidden border border-gray-200 dark:border-white/5 group-hover:border-teal-500/30 transition-all mb-2 shadow-sm">
                     <img src={item.thumbnailUrl} alt={title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                     <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent"></div>
                     <div className="absolute bottom-2 left-2 right-2">
                        <span className="px-2 py-0.5 bg-teal-500/90 rounded text-[10px] font-bold text-white mb-1 inline-block">Editor's Choice</span>
                     </div>
                  </div>
                  <h4 className="font-bold text-sm text-gray-800 dark:text-slate-200 group-hover:text-teal-600 dark:group-hover:text-teal-400 transition-colors leading-snug">
                     {title}
                  </h4>
                </Link>
               )
            })}
         </div>
      </div>

      {/* BLOCK 4: DID YOU KNOW */}
      <div>
         <FactBox fact={todaysFact} />
      </div>

      {/* BLOCK 5: CATEGORY JUMP */}
      <div className="bg-white dark:bg-[#151E32]/50 rounded-xl p-5 border border-gray-100 dark:border-white/5 shadow-sm">
         <SidebarHeader title={t('sb_categories')} />
         <div className="flex flex-wrap gap-2">
            {CATEGORIES.map(cat => (
               <Link 
                 key={cat.id} 
                 to={`/categories?filter=${cat.slug}`}
                 className="px-3 py-1.5 bg-gray-50 dark:bg-white/5 hover:bg-primary-50 dark:hover:bg-primary-500/20 text-gray-600 dark:text-slate-400 hover:text-primary-600 dark:hover:text-primary-400 border border-gray-200 dark:border-white/5 hover:border-primary-200 dark:hover:border-primary-500/30 rounded-full text-xs font-medium transition-all shadow-sm dark:hover:shadow-glow"
               >
                 {cat.label}
               </Link>
            ))}
         </div>
      </div>

      {/* BLOCK 10: QUOTE OF THE DAY */}
      <div className="relative p-6 text-center rounded-xl border border-gray-100 dark:border-white/5 bg-gradient-to-b from-white to-gray-50 dark:from-[#151E32] dark:to-[#0B1120] overflow-hidden group shadow-sm">
         <QuoteIcon size={40} className="text-gray-200 dark:text-white/5 absolute top-2 left-2" />
         <h3 className="text-xs font-bold text-primary-600 dark:text-primary-500 uppercase tracking-widest mb-3 relative z-10">{t('sb_quote')}</h3>
         <blockquote className="text-gray-700 dark:text-slate-300 font-serif italic text-lg leading-relaxed mb-3 relative z-10">
            "{isEn ? todaysQuote.text_en : todaysQuote.text}"
         </blockquote>
         <cite className="text-xs text-gray-500 dark:text-slate-500 font-medium not-italic relative z-10">— {todaysQuote.author}</cite>
      </div>

      {/* BLOCK 6: LATEST UPDATES */}
      <div>
         <SidebarHeader title={t('sb_latest')} />
         <div className="divide-y divide-gray-100 dark:divide-white/5">
            {latest.map(item => (
               <CompactContentItem 
                 key={item.id} 
                 item={item} 
                 showImage={false}
                 metaIcon={<Clock size={10} />}
                 metaText={t('time_just_now')}
               />
            ))}
         </div>
      </div>

    </aside>
  );
};

