                className={`text-sm font-medium transition-all duration-200 relative ${
                  isActive(link.path)
                    ? 'text-brand-purple dark:text-primary-400 font-semibold'
                    : 'text-gray-600 dark:text-slate-400 hover:text-brand-purple dark:hover:text-primary-300'
                }`}
              >
                {link.label}
                {isActive(link.path) && (
                  <span className="absolute -bottom-6 left-0 w-full h-0.5 bg-gradient-brand shadow-sm"></span>
                )}
              </Link>
            ))}
          </div>

          {/* Center: Search Bar (Desktop) */}
          <div className="hidden md:flex flex-1 max-w-lg">
             <form onSubmit={handleSearch} className="w-full relative group">
                <input 
                  type="text" 
                  value={searchValue}
                  onChange={(e) => setSearchValue(e.target.value)}
                  placeholder={t('search_placeholder')}
                  className="w-full pl-10 pr-4 py-2.5 rounded-full bg-gray-100 dark:bg-white/5 border border-transparent dark:border-white/10 text-gray-900 dark:text-slate-200 placeholder-gray-500 dark:placeholder-slate-500 focus:ring-2 focus:ring-brand-purple/30 focus:border-brand-purple/50 outline-none transition-all group-hover:bg-white dark:group-hover:bg-white/10"
                />
