             </form>
          </div>

          {/* Right: Actions */}
          <div className="flex items-center gap-3">

            {/* Language Toggle */}
            <button 
               onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
               className="hidden sm:flex items-center gap-1 text-xs font-bold px-2 py-1 rounded transition-colors"
            >
               <span className={language === 'mn' ? 'text-brand-purple dark:text-primary-400' : 'text-gray-400 dark:text-slate-600'}>MN</span>
               <span className="text-gray-300 dark:text-slate-700">|</span>
               <span className={language === 'en' ? 'text-brand-purple dark:text-primary-400' : 'text-gray-400 dark:text-slate-600'}>EN</span>
            </button>

            {/* Theme Toggle */}
            <button
              onClick={toggleTheme}
              className="p-2 rounded-full text-gray-500 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-brand-orange dark:hover:text-brand-orange transition-colors"
