              {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
            </button>

            <button className="hidden md:flex items-center gap-2 px-6 py-2 bg-gradient-brand text-white rounded-full text-sm font-semibold hover:opacity-90 shadow-md hover:shadow-glow transition-all hover:-translate-y-0.5">
              <User size={18} />
              <span>{t('login')}</span>
            </button>

            {/* Mobile menu button */}
            <button
              onClick={() => setIsOpen(!isOpen)}
              className="lg:hidden p-2 rounded-md text-gray-600 dark:text-slate-400 hover:text-brand-purple dark:hover:text-primary-400 focus:outline-none"
            >
              {isOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
          </div>
        </div>
      </div>

      {/* Mobile Menu */}
      {isOpen && (
        <div className="lg:hidden bg-white/95 dark:bg-[#020617]/95 backdrop-blur-xl border-t border-gray-100 dark:border-white/5 absolute w-full left-0 shadow-2xl">
