                />
                <Search size={18} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400 dark:text-slate-500" />
            </form>

            <div className="space-y-1">
              {navLinks.map((link) => (
                <Link
                  key={link.path}
                  to={link.path}
                  onClick={() => setIsOpen(false)}
                  className={`block px-3 py-3 rounded-lg text-base font-medium ${
                    isActive(link.path)
                      ? 'text-brand-purple dark:text-primary-400 bg-purple-50 dark:bg-white/5'
                      : 'text-gray-600 dark:text-slate-400 hover:bg-gray-50 dark:hover:bg-white/5'
                  }`}
                >
                  {link.label}
                </Link>
              ))}
            </div>

            <div className="pt-4 border-t border-gray-100 dark:border-white/5 space-y-3">
               <button className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-gradient-brand text-white rounded-xl text-sm font-semibold shadow-md">
                <User size={18} />
                <span>{t('login')}</span>
              </button>

              <div className="flex items-center justify-between px-2">
                 <button onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')} className="text-sm font-medium text-gray-600 dark:text-slate-400">
                    {language === 'mn' ? 'Mongolian' : 'English'}
                 </button>
                 <button onClick={toggleTheme} className="flex items-center gap-2 text-sm font-medium text-gray-600 dark:text-slate-400">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                    <span>{theme === 'dark' ? t('theme_light') : t('theme_dark')}</span>
