                   {item.isVideo ? t('watch') : t('read')}
                </span>
             </div>
          )}
        </div>
      </div>
    </Link>
  );
};

import React from 'react';
import { Link } from 'react-router-dom';
import { Flame, Eye, Bookmark, Clock, Quote as QuoteIcon } from 'lucide-react';
import { MOCK_CONTENT, CATEGORIES, QUOTES, INTERESTING_FACTS } from '../constants';
import { useLanguage } from '../context/LanguageContext';
import { FactBox } from './FactBox';
import { ContentItem } from '../types';

export const Sidebar: React.FC = () => {
  const { t, language } = useLanguage();
  const isEn = language === 'en';

  // --- DATA PROCESSING ---
  const mostViewed = [...MOCK_CONTENT].sort((a, b) => b.views - a.views).slice(0, 5);
  const trending = MOCK_CONTENT.filter(c => c.isTrending).slice(0, 5);
  const editorsPick = MOCK_CONTENT.filter(c => c.isEditorPick).slice(0, 3);
  const latest = [...MOCK_CONTENT].sort((a, b) => new Date(b.publishedDate).getTime() - new Date(a.publishedDate).getTime()).slice(0, 4);
  const todaysQuote = QUOTES[0];
  const todaysFact = INTERESTING_FACTS[language][0];

  // --- SUB-COMPONENTS ---

  const SidebarHeader: React.FC<{ title: string; icon?: React.ReactNode }> = ({ title, icon }) => (
    <h3 className="flex items-center gap-2 font-bold text-gray-900 dark:text-white mb-5 text-sm uppercase tracking-wider pl-1">
      {icon}
      {title}
    </h3>
  );

  const CompactContentItem: React.FC<{ item: ContentItem; rank?: number; showImage?: boolean; metaIcon?: React.ReactNode; metaText?: string }> = ({ 
    item, rank, showImage = true, metaIcon, metaText 
  }) => {
    const title = isEn ? item.title_en : item.title;

    return (
      <Link to={`/watch/${item.id}`} className="group flex gap-3 items-start p-2 rounded-xl hover:bg-gray-50 dark:hover:bg-white/5 transition-all">
        {showImage && (
          <div className={`relative flex-shrink-0 overflow-hidden rounded-lg border border-gray-100 dark:border-white/5 ${rank === 1 ? 'w-24 h-16 shadow-md' : 'w-16 h-12'}`}>
            <img src={item.thumbnailUrl} alt={title} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500" />

            {/* TOP Badge for #1 */}
            {rank === 1 && (
               <div className="absolute top-0 left-0 px-1.5 py-0.5 bg-gradient-brand rounded-br-lg text-[10px] font-bold text-white shadow-sm">
                 TOP
               </div>
            )}
            {rank && rank > 1 && (
               <div className="absolute top-0 left-0 w-5 h-5 bg-gray-900/80 backdrop-blur-sm flex items-center justify-center text-[10px] font-bold text-white rounded-br-lg">
                 {rank}
               </div>
            )}
          </div>
        )}
        <div className="flex-1 min-w-0">
          <h4 className={`font-medium text-gray-700 dark:text-slate-300 group-hover:text-brand-purple dark:group-hover:text-primary-300 transition-colors leading-snug line-clamp-2 ${rank === 1 ? 'text-sm font-bold text-gray-900 dark:text-white' : 'text-xs'}`}>
            {title}
          </h4>
          <div className="flex items-center gap-2 mt-1.5 text-[10px] text-gray-400 dark:text-slate-500 font-medium">
             {metaIcon}
             <span>{metaText}</span>
          </div>
        </div>
      </Link>
    );
  };

  return (
    <aside className="space-y-10 sticky top-24">

      {/* BLOCK 1: MOST VIEWED */}
      <div className="bg-white dark:bg-brand-surface rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-soft dark:shadow-none">
        <SidebarHeader title={t('sb_most_viewed')} icon={<Eye size={16} className="text-brand-purple" />} />
        <div className="space-y-2">
          {mostViewed.map((item, idx) => (
            <CompactContentItem 
              key={item.id} 
              item={item} 
              rank={idx + 1} 
              metaIcon={<Eye size={10} />}
              metaText={`${(item.views / 1000).toFixed(1)}k`}
            />
          ))}
        </div>
      </div>

      {/* BLOCK 2: TRENDING */}
      <div className="bg-white dark:bg-brand-surface rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-soft dark:shadow-none relative overflow-hidden group">
        <div className="absolute top-0 right-0 w-32 h-32 bg-brand-orange/10 rounded-full blur-3xl pointer-events-none -mr-16 -mt-16 group-hover:bg-brand-orange/20 transition-colors"></div>
        <SidebarHeader title={t('sb_trending')} icon={<Flame size={16} className="text-brand-orange" />} />
        <div className="space-y-4 relative z-10">
           {trending.map(item => (
              <CompactContentItem 
                key={item.id} 
                item={item} 
                metaIcon={<Clock size={10} />}
                metaText="2h ago"
              />
           ))}
        </div>
      </div>

      {/* BLOCK 3: EDITOR'S PICK */}
      <div>
         <SidebarHeader title={t('sb_editors_pick')} icon={<Bookmark size={16} className="text-brand-purple" />} />
         <div className="space-y-5">
            {editorsPick.map(item => {
               const title = isEn ? item.title_en : item.title;
               return (
                <Link key={item.id} to={`/watch/${item.id}`} className="block group">
                  <div className="relative aspect-[16/9] rounded-xl overflow-hidden border border-gray-100 dark:border-white/5 mb-3 shadow-sm">
                     <img src={item.thumbnailUrl} alt={title} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-700" />
                     <div className="absolute inset-0 bg-gradient-to-t from-[#020617]/80 to-transparent"></div>
                     <div className="absolute bottom-3 left-3">
                        <span className="px-2 py-1 bg-brand-purple/90 backdrop-blur-sm rounded text-[10px] font-bold text-white tracking-wide">EDITOR'S PICK</span>
                     </div>
                  </div>
                  <h4 className="font-bold text-sm text-gray-900 dark:text-white group-hover:text-brand-purple dark:group-hover:text-primary-300 transition-colors leading-snug">
                     {title}
                  </h4>
                </Link>
               )
            })}
         </div>
      </div>

      {/* BLOCK 4: DID YOU KNOW */}
      <div>
         <FactBox fact={todaysFact} />
      </div>

      {/* BLOCK 5: CATEGORY JUMP */}
      <div className="bg-white dark:bg-brand-surface rounded-2xl p-6 border border-gray-100 dark:border-white/5 shadow-soft dark:shadow-none">
         <SidebarHeader title={t('sb_categories')} />
         <div className="flex flex-wrap gap-2">
            {CATEGORIES.map(cat => (
               <Link 
                 key={cat.id} 
                 to={`/categories?filter=${cat.slug}`}
                 className="px-4 py-2 bg-gray-50 dark:bg-white/5 hover:bg-gradient-brand text-gray-600 dark:text-slate-400 hover:text-white border border-gray-200 dark:border-white/5 hover:border-transparent rounded-lg text-xs font-semibold transition-all shadow-sm hover:shadow-md"
               >
                 {cat.label}
               </Link>
            ))}
         </div>
      </div>

      {/* BLOCK 6: LATEST UPDATES */}
      <div>
         <SidebarHeader title={t('sb_latest')} />
         <div className="divide-y divide-gray-100 dark:divide-white/5">
            {latest.map(item => (
               <CompactContentItem 
                 key={item.id} 
                 item={item} 
                 showImage={false}
                 metaIcon={<Clock size={10} />}
                 metaText={t('time_just_now')}
               />
            ))}
         </div>
      </div>

       {/* BLOCK 10: QUOTE OF THE DAY */}
      <div className="relative p-8 text-center rounded-2xl border border-gray-100 dark:border-white/5 bg-gradient-to-br from-white to-gray-50 dark:from-brand-surface dark:to-[#020617] overflow-hidden group shadow-soft dark:shadow-none">
         <QuoteIcon size={48} className="text-gray-100 dark:text-white/5 absolute top-4 left-4" />
         <h3 className="text-xs font-bold text-brand-purple uppercase tracking-widest mb-4 relative z-10 opacity-80">{t('sb_quote')}</h3>
         <blockquote className="text-gray-800 dark:text-slate-200 font-serif italic text-lg leading-relaxed mb-4 relative z-10">
            "{isEn ? todaysQuote.text_en : todaysQuote.text}"
         </blockquote>
         <div className="w-8 h-1 bg-gradient-brand mx-auto mb-3 rounded-full opacity-50"></div>
         <cite className="text-xs text-gray-500 dark:text-slate-500 font-bold not-italic relative z-10 uppercase tracking-wide">{todaysQuote.author}</cite>
      </div>

    </aside>
  );
};

import React, { useState } from 'react';
import { Menu, X, Search, User, Moon, Sun, ChevronDown } from 'lucide-react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { useTheme } from '../context/ThemeContext';
import { CATEGORIES } from '../constants';

export const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const location = useLocation();
  const navigate = useNavigate();
  const { t, language, setLanguage } = useLanguage();
  const { theme, toggleTheme } = useTheme();

  const isActive = (path: string) => location.pathname === path;
  const isCategoryActive = (slug: string) => location.search === `?filter=${slug}`;

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchValue.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchValue)}`);
      setIsOpen(false);
    }
  };

  // Main navigation items for desktop (Row 2)
  const mainNavItems = [
    { label: t('nav_home'), path: '/', type: 'link' },
    ...CATEGORIES.map(cat => ({
       label: cat.label,
       path: `/categories?filter=${cat.slug}`,
       slug: cat.slug,
       type: 'category'
    })),
    { label: t('nav_video'), path: '/categories?filter=video', type: 'link' }
  ];

  return (
    <nav className="sticky top-0 z-50 transition-all duration-300">

       {/* Background with blur and gradient - Wraps both rows */}
       <div className="absolute inset-0 bg-[#0B1120]/90 dark:bg-[#020617]/90 backdrop-blur-xl border-b border-white/5 shadow-lg">
          {/* Subtle gradient overlay */}
          <div className="absolute inset-0 bg-gradient-to-r from-brand-purple/5 via-transparent to-brand-orange/5 pointer-events-none"></div>
       </div>

       <div className="relative z-10">

          {/* TOP ROW: Brand, Search, Utilities */}
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
            <div className="flex h-16 items-center justify-between gap-6 border-b border-white/5">

              {/* Left: Logo */}
              <Link to="/" className="flex-shrink-0 flex items-center gap-2 group">
                <span className="font-bold text-xl md:text-2xl tracking-wide text-gradient transition-all duration-300 group-hover:drop-shadow-glow">
                  Channel Mongolia
                </span>
              </Link>

              {/* Center: Search Bar (Desktop) */}
              <div className="hidden md:flex flex-1 max-w-xl mx-auto">
                <form onSubmit={handleSearch} className="w-full relative group">
                    <input 
                      type="text" 
                      value={searchValue}
                      onChange={(e) => setSearchValue(e.target.value)}
                      placeholder={t('search_placeholder')}
                      className="w-full pl-11 pr-4 py-2.5 rounded-xl bg-white/5 border border-white/10 text-slate-200 placeholder-slate-500 focus:bg-[#0F172A] focus:border-brand-purple/50 focus:ring-1 focus:ring-brand-purple/50 outline-none transition-all duration-300 group-hover:border-white/20"
                    />
                    <Search size={18} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500 group-hover:text-brand-purple transition-colors" />
                </form>
              </div>

              {/* Right: Actions */}
              <div className="flex items-center gap-4">

                {/* Language Toggle */}
                <button 
                  onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
                  className="hidden sm:flex items-center gap-1 text-xs font-bold px-2 py-1 rounded transition-colors text-slate-400 hover:text-slate-200"
                >
                  <span className={language === 'mn' ? 'text-brand-purple' : ''}>MN</span>
                  <span className="text-white/20">|</span>
                  <span className={language === 'en' ? 'text-brand-purple' : ''}>EN</span>
                </button>

                {/* Theme Toggle */}
                <button
                  onClick={toggleTheme}
                  className="p-2 rounded-full text-slate-400 hover:bg-white/5 hover:text-brand-orange transition-colors"
                  title={theme === 'dark' ? t('theme_light') : t('theme_dark')}
                >
                  {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
                </button>

                {/* Login Button */}
                <button className="hidden md:flex items-center gap-2 px-5 py-2 bg-gradient-brand text-white rounded-full text-sm font-semibold hover:opacity-90 shadow-md hover:shadow-glow transition-all hover:-translate-y-0.5">
                  <User size={18} />
                  <span>{t('login')}</span>
                </button>

                {/* Mobile menu button */}
                <button
                  onClick={() => setIsOpen(!isOpen)}
                  className="lg:hidden p-2 rounded-md text-slate-400 hover:text-white focus:outline-none"
                >
                  {isOpen ? <X size={24} /> : <Menu size={24} />}
                </button>
              </div>
            </div>
          </div>

          {/* BOTTOM ROW: Navigation Categories (Desktop) */}
          <div className="hidden lg:block max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
             <div className="flex items-center h-12 gap-8 overflow-x-auto no-scrollbar mask-fade-right">
                {mainNavItems.map((item) => {
                   const active = item.type === 'category' && item.slug 
                      ? isCategoryActive(item.slug) 
                      : isActive(item.path);

                   return (
                    <Link
                      key={item.label}
                      to={item.path}
                      className={`text-sm font-medium whitespace-nowrap transition-all duration-200 relative group flex flex-col justify-center h-full px-1 ${
                        active
                          ? 'text-slate-100'
                          : 'text-slate-400 hover:text-transparent hover:bg-clip-text hover:bg-gradient-brand'
                      }`}
                    >
                      <span>{item.label}</span>
                      {/* Active / Hover Glow */}
                      <span className={`absolute bottom-0 left-0 w-full h-[2px] rounded-t-full transition-all duration-300 ${
                         active ? 'bg-gradient-brand opacity-100 shadow-[0_-2px_8px_rgba(109,40,217,0.5)]' : 'bg-transparent opacity-0 group-hover:bg-gradient-brand group-hover:opacity-50'
                      }`}></span>
                    </Link>
                   );
                })}
             </div>
          </div>
       </div>

      {/* Mobile Menu Drawer */}
      {isOpen && (
        <div className="lg:hidden fixed inset-0 z-50 bg-[#020617] flex flex-col animate-fade-in">
           {/* Header of Drawer */}
           <div className="flex items-center justify-between p-4 border-b border-white/10 bg-[#0B1120]">
              <span className="font-bold text-xl text-gradient">Channel Mongolia</span>
              <button onClick={() => setIsOpen(false)} className="p-2 text-slate-400 hover:text-white">
                 <X size={24} />
              </button>
           </div>

          <div className="flex-1 overflow-y-auto px-4 py-6 space-y-6">
            <form onSubmit={handleSearch} className="relative">
                <input 
                  type="text" 
                  value={searchValue}
                  onChange={(e) => setSearchValue(e.target.value)}
                  placeholder={t('search_placeholder')}
                  className="w-full pl-11 pr-4 py-3.5 rounded-xl bg-white/5 border border-white/10 text-slate-200 text-base focus:border-brand-purple/50 focus:bg-[#0F172A]"
                />
                <Search size={20} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-slate-500" />
            </form>

            <div className="space-y-1">
              {mainNavItems.map((item) => {
                 const active = item.type === 'category' && item.slug 
                      ? isCategoryActive(item.slug) 
                      : isActive(item.path);
                 return (
                  <Link
                    key={item.label}
                    to={item.path}
                    onClick={() => setIsOpen(false)}
                    className={`block px-4 py-3.5 rounded-xl text-base font-medium transition-all ${
                      active
                        ? 'bg-gradient-brand text-white shadow-glow'
                        : 'text-slate-400 hover:bg-white/5 hover:text-white'
                    }`}
                  >
                    {item.label}
                  </Link>
                 );
              })}
            </div>
          </div>

          {/* Footer of Drawer */}
          <div className="p-4 border-t border-white/10 bg-[#0B1120] space-y-3">
             <button className="w-full flex items-center justify-center gap-2 px-4 py-3.5 bg-gradient-brand text-white rounded-xl text-sm font-bold shadow-md">
                <User size={18} />
                <span>{t('login')}</span>
              </button>

              <div className="flex items-center justify-between px-2 pt-2">
                 <button onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')} className="text-sm font-medium text-slate-400 hover:text-white">
                    {language === 'mn' ? 'Монгол хэл' : 'English'}
                 </button>
                 <button onClick={toggleTheme} className="flex items-center gap-2 text-sm font-medium text-slate-400 hover:text-white">
                    {theme === 'dark' ? <Sun size={18} /> : <Moon size={18} />}
                    <span>{theme === 'dark' ? t('theme_light') : t('theme_dark')}</span>
                 </button>
              </div>
          </div>
        </div>
      )}
    </nav>
  );
};

