              className={`p-2 rounded-full transition-colors ${
                input.trim() && !isLoading
                  ? 'text-brand-purple hover:bg-brand-purple/10'
                  : 'text-gray-400 cursor-not-allowed'
              }`}
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      </div>
    </>
  );
};

