    };

    setAdminContent(prev => [newDraft, ...prev]);
    return newDraft;
  };

  const saveContent = (content: ContentItem) => {
    setAdminContent(prev => {
      const exists = prev.find(c => c.id === content.id);
      if (exists) {
        return prev.map(c => c.id === content.id ? content : c);
      }
      return [content, ...prev];
