        </div>

        {/* Suggested Questions (Chips) */}
        {!isLoading && messages.length < 5 && (
           <div className="px-4 pb-2 bg-gray-50 dark:bg-[#020617]/50 overflow-x-auto no-scrollbar flex gap-2">
