export default function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  const { password } = req.body;
  const secret = process.env.ADMIN_SECRET;

  if (!secret) {
    console.error("ADMIN_SECRET is not set on server.");
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  if (password === secret) {
    // Generate a simple token (In production, use a signed JWT)
    // We base64 encode the secret + timestamp to create a rudimentary session token
    // that the server can verify by checking if it contains the secret.
    const token = Buffer.from(`${secret}::${Date.now()}`).toString('base64');
    return res.status(200).json({ success: true, token });
  }

  return res.status(401).json({ success: false });
}

import { createClient } from '@supabase/supabase-js';

// Initialize Supabase Client (Server-side)
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_ANON_KEY;
const supabase = (supabaseUrl && supabaseKey) 
  ? createClient(supabaseUrl, supabaseKey) 
  : null;

export default async function handler(req, res) {
  const { method } = req;

  // --- GET: Fetch Content (Public) ---
  if (method === 'GET') {
    if (!supabase) {
      // Fallback to empty if no DB (Client will use Mock)
      return res.status(200).json({ data: [] });
    }

    const { data, error } = await supabase
      .from('content')
      .select('*')
      .order('updated_at', { ascending: false });

    if (error) return res.status(500).json({ error: error.message });

    // Map snake_case DB to camelCase frontend
    const mappedData = data.map(item => ({
      id: item.id,
      title: item.title,
      title_en: item.title_en,
      description: item.description,
      description_en: item.description_en,
      contentBody: item.content_body,
      contentBody_en: item.content_body_en,
      category: item.category,
      category_en: item.category_en,
      thumbnailUrl: item.thumbnail_url,
      views: item.views,
      publishedDate: item.published_date,
      readTime: item.read_time,
      readTimeValue: item.read_time_value,
      isVideo: item.is_video,
      tags: item.tags,
      tags_en: item.tags_en,
      status: item.status
    }));

    return res.status(200).json({ data: mappedData });
  }

  // --- POST/PUT: Write Content (Admin Only) ---
  if (method === 'POST' || method === 'PUT') {
    // Security Check
    const authHeader = req.headers.authorization;
    const secret = process.env.ADMIN_SECRET;

    if (!authHeader || !secret) {
        return res.status(401).json({ error: 'Unauthorized' });
    }

    // Verify rudimentary token
    try {
        const decoded = Buffer.from(authHeader.replace('Bearer ', ''), 'base64').toString();
        if (!decoded.startsWith(secret)) {
            throw new Error('Invalid token');
        }
    } catch (e) {
        return res.status(401).json({ error: 'Invalid Token' });
    }

    if (!supabase) {
        return res.status(503).json({ error: 'Database not configured' });
    }

    const body = req.body;

    // Map camelCase frontend to snake_case DB
    const dbPayload = {
      id: body.id,
      title: body.title,
      title_en: body.title_en,
      description: body.description,
      description_en: body.description_en,
      content_body: body.contentBody,
      content_body_en: body.contentBody_en,
      category: body.category,
      category_en: body.category_en,
      thumbnail_url: body.thumbnailUrl,
      views: body.views,
      published_date: body.publishedDate,
      read_time: body.readTime,
      read_time_value: body.readTimeValue,
      is_video: body.isVideo,
      tags: body.tags,
      tags_en: body.tags_en,
      status: body.status,
      updated_at: new Date().toISOString()
    };

    const { data, error } = await supabase
        .from('content')
        .upsert(dbPayload)
        .select();

    if (error) return res.status(500).json({ error: error.message });
    return res.status(200).json({ success: true, data });
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

import { GoogleGenAI } from '@google/genai';

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // 1. Security Check
  const authHeader = req.headers.authorization;
  const secret = process.env.ADMIN_SECRET;

  if (!authHeader || !secret) {
      return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
      const decoded = Buffer.from(authHeader.replace('Bearer ', ''), 'base64').toString();
      if (!decoded.startsWith(secret)) {
          throw new Error('Invalid token');
      }
  } catch (e) {
      return res.status(401).json({ error: 'Invalid Token' });
  }

  // 2. Initialize Gemini
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: 'Gemini API Key missing' });
  }

  const { action, text, language, context } = req.body;
  const ai = new GoogleGenAI({ apiKey });

  // 3. Construct Prompt
  let prompt = "";
  const langName = language === 'mn' ? 'Mongolian' : 'English';

  switch (action) {
    case 'improve':
      prompt = `Improve the following ${langName} text to be more engaging and professional, keeping the same meaning:\n\n"${text}"`;
      break;
    case 'summarize':
      prompt = `Summarize the following text in ${langName} into 2-3 sentences:\n\n"${text}"`;
      break;
    case 'expand':
      prompt = `Expand on the following ${langName} text with more details and explanation, suitable for an educational article:\n\n"${text}"`;
      break;
    case 'translate':
      const targetLang = language === 'mn' ? 'English' : 'Mongolian';
      prompt = `Translate the following text to ${targetLang}. Return ONLY the translated text:\n\n"${text}"`;
      break;
    case 'generate':
      prompt = `Write a detailed, engaging blog post section in ${langName} about: "${text}". Use a professional yet accessible tone.`;
      break;
    default:
      return res.status(400).json({ error: 'Invalid action' });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return res.status(200).json({ result: response.text });
  } catch (error) {
    console.error('AI Error:', error);
    return res.status(500).json({ error: error.message });
  }
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ContentItem } from '../types';
import { MOCK_CONTENT } from '../constants';

interface ContentContextType {
  content: ContentItem[];
  loading: boolean;
  refreshContent: () => Promise<void>;
}

const ContentContext = createContext<ContentContextType | undefined>(undefined);

export const ContentProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [content, setContent] = useState<ContentItem[]>(MOCK_CONTENT);
  const [loading, setLoading] = useState(true);

  const fetchContent = async () => {
    try {
      const res = await fetch('/api/content');
      if (res.ok) {
        const json = await res.json();
        if (json.data && json.data.length > 0) {
          // Merge API content with MOCK content (API takes precedence)
          // validIds tracks IDs from API to avoid duplicates if we want to keep some mocks
          // For now, let's replace mocks if API returns data, or append/merge.
          // Strategy: Use API data. If API has data, use it. 
          // If we want to strictly keep MOCKs for demo when API empty:

          setContent(json.data);
        } else {
          // Fallback to mocks if DB empty
          setContent(MOCK_CONTENT);
        }
      }
    } catch (e) {
      console.error("Failed to fetch content, using mocks", e);
      setContent(MOCK_CONTENT);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchContent();
  }, []);

  return (
    <ContentContext.Provider value={{ content, loading, refreshContent: fetchContent }}>
      {children}
    </ContentContext.Provider>
  );
};

export const useContent = () => {
  const context = useContext(ContentContext);
  if (context === undefined) {
    throw new Error('useContent must be used within a ContentProvider');
  }
  return context;
};

