import React from 'react';
import { CATEGORIES } from '../constants';
import { useContent } from '../context/ContentContext';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { Filter } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import { useNavigate } from 'react-router-dom';

interface CategoriesPageProps {
    categorySlug?: string;
    filter?: string; 
}

export const CategoriesPage: React.FC<CategoriesPageProps> = ({ categorySlug, filter }) => {
  const { t, language } = useLanguage();
  const navigate = useNavigate();
  const { content } = useContent(); // Dynamic Content

  const activeSlug = categorySlug || filter || 'all';

  const handleFilterChange = (slug: string) => {
    if (slug === 'all') navigate('/categories');
    else navigate(`/${slug}`);
  };

  const activeCategoryLabel = (() => {
      if (activeSlug === 'all') return t('all_knowledge');
      if (activeSlug === 'video') return t('video_knowledge');
      return CATEGORIES.find(c => c.slug === activeSlug)?.label || t('nav_categories');
  })();

  const filteredContent = (() => {
      if (activeSlug === 'all') return content;
      if (activeSlug === 'video') return content.filter(c => c.isVideo);

      const catObj = CATEGORIES.find(cat => cat.slug === activeSlug);
      return catObj 
         ? content.filter(c => c.category === catObj.label || c.category_en === catObj.label_en)
         : content;
  })();

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8">
        <h1 className="text-3xl font-extrabold text-gray-900 dark:text-white mb-4 md:mb-0 drop-shadow-sm dark:drop-shadow-md">
          {activeCategoryLabel}
        </h1>

        <div className="flex items-center gap-3">
            <span className="text-sm text-slate-500 font-medium">{t('sort_by')}</span>
            <button className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-brand-surface border border-gray-200 dark:border-white/10 rounded-lg text-sm font-medium hover:bg-gray-50 dark:hover:bg-white/5 text-gray-700 dark:text-slate-300 transition-colors">
                <Filter size={16} />
                <span>{t('newest')}</span>
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

        <div className="lg:col-span-1">
            <div className="bg-white dark:bg-brand-surface p-4 rounded-xl shadow-lg border border-gray-200 dark:border-white/5 sticky top-24">
                <h3 className="font-bold text-gray-900 dark:text-slate-200 mb-4 px-2">{t('nav_categories')}</h3>
                <div className="space-y-1">
                    <button
                        onClick={() => handleFilterChange('all')}
                        className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                            activeSlug === 'all' 
                            ? 'bg-primary-50 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 border border-primary-200 dark:border-primary-500/20 shadow-sm dark:shadow-glow' 
                            : 'text-slate-600 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-slate-200'
                        }`}
                    >
                        {t('all_knowledge')}
                    </button>
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => handleFilterChange(cat.slug)}
                            className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                                activeSlug === cat.slug 
                                ? 'bg-primary-50 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400 border border-primary-200 dark:border-primary-500/20 shadow-sm dark:shadow-glow' 
                                : 'text-slate-600 dark:text-slate-400 hover:bg-gray-100 dark:hover:bg-white/5 hover:text-slate-900 dark:hover:text-slate-200'
                            }`}
                        >
                            {cat.label}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="lg:col-span-3">
            {filteredContent.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 gap-8">
                    {filteredContent.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
            ) : (
                <div className="py-20 text-center bg-white dark:bg-brand-surface rounded-xl border border-dashed border-gray-200 dark:border-white/10">
                    <p className="text-slate-500">{t('no_results')}</p>
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search as SearchIcon } from 'lucide-react';
import { useContent } from '../context/ContentContext';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { useSearchParams } from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [searchTerm, setSearchTerm] = useState(query);
  const { t, language } = useLanguage();
  const { content } = useContent(); // Dynamic
  const isEn = language === 'en';

  useEffect(() => {
    setSearchTerm(query);
  }, [query]);

  const filtered = searchTerm 
    ? content.filter(c => {
        const title = isEn ? c.title_en : c.title;
        const desc = isEn ? c.description_en : c.description;
        return (title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
               (desc || '').toLowerCase().includes(searchTerm.toLowerCase());
      })
    : [];

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 min-h-[60vh]">
        <div className="max-w-2xl mx-auto mb-16">
            <h1 className="text-3xl font-bold text-center text-gray-900 dark:text-slate-100 mb-8 drop-shadow-sm dark:drop-shadow-md">{t('search_placeholder')}</h1>
            <div className="relative group">
                <input
                    type="text"
                    placeholder={t('search_placeholder')}
                    className="w-full pl-14 pr-6 py-4 rounded-2xl border border-gray-200 dark:border-white/10 bg-white dark:bg-brand-surface focus:border-primary-500 focus:ring-4 focus:ring-primary-500/20 outline-none text-lg text-gray-900 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 shadow-lg transition-all"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    autoFocus
                />
                <SearchIcon className="absolute left-5 top-1/2 transform -translate-y-1/2 text-slate-400 dark:text-slate-500 group-focus-within:text-primary-500 dark:group-focus-within:text-primary-400 transition-colors" size={24} />
            </div>
        </div>

        {searchTerm && (
            <div>
                <h2 className="text-lg font-bold text-gray-900 dark:text-slate-200 mb-8 pb-4 border-b border-gray-200 dark:border-white/10">
                    {t('search_results')} <span className="text-primary-600 dark:text-primary-400 ml-2">{filtered.length}</span>
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    {filtered.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
                {filtered.length === 0 && (
                    <div className="text-center py-16 bg-white dark:bg-brand-surface rounded-2xl border border-dashed border-gray-200 dark:border-white/10">
                         <p className="text-slate-500 text-lg">{t('no_results')}</p>
                    </div>
                )}
            </div>
        )}

        {!searchTerm && (
            <div className="text-center">
                 <p className="text-slate-500 dark:text-slate-600 text-sm">Channel Mongolia</p>
            </div>
        )}
    </div>
  );
};

import { createClient } from '@supabase/supabase-js';

// Initialize Supabase (Server-side)
// We use SERVICE_ROLE_KEY for writes to bypass RLS policies if needed, 
// or ensure we have admin privileges.
const supabaseUrl = process.env.SUPABASE_URL;
const supabaseAnonKey = process.env.SUPABASE_ANON_KEY;
const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

export default async function handler(req, res) {
  const { method } = req;

  // --- GET: Public Fetch ---
  if (method === 'GET') {
    if (!supabaseUrl || !supabaseAnonKey) {
      // Return empty list if DB not configured (prevents crash)
      return res.status(200).json({ data: [] });
    }

    const supabase = createClient(supabaseUrl, supabaseAnonKey);

    // Fetch published content
    const { data, error } = await supabase
      .from('content')
      .select('*')
      .eq('status', 'published')
      .order('updated_at', { ascending: false });

    if (error) {
      return res.status(500).json({ error: error.message });
    }

    // Map DB Snake_case to CamelCase for Frontend
    const mappedData = data.map(item => ({
      id: item.id,
      title: item.title,
      description: item.description,
      contentBody: item.body_html, // HTML body
      category: item.category,
      thumbnailUrl: item.thumbnail_url,
      readTimeValue: item.read_time_value,
      tags: item.tags,
      status: item.status,
      publishedDate: new Date(item.updated_at).toLocaleDateString()
    }));

    return res.status(200).json({ data: mappedData });
  }

  // --- POST/PUT: Admin Write ---
  if (method === 'POST' || method === 'PUT') {
    const authHeader = req.headers.authorization;
    const secret = process.env.ADMIN_SECRET;

    // 1. Verify Secret
    if (!authHeader || !secret) {
        return res.status(401).json({ error: 'Unauthorized' });
    }
    const token = authHeader.replace('Bearer ', '');
    // Simple verification: token should contain secret
    // In production, use JWT verification
    try {
       const decoded = Buffer.from(token, 'base64').toString();
       if (!decoded.startsWith(secret)) throw new Error('Invalid token');
    } catch(e) {
       return res.status(401).json({ error: 'Invalid Token' });
    }

    // 2. Initialize Admin Client
    if (!supabaseUrl || !supabaseServiceKey) {
        return res.status(503).json({ error: 'Database not configured' });
    }
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

    const body = req.body;

    // Map CamelCase to DB Snake_case
    const dbPayload = {
      id: body.id,
      title: body.title,
      description: body.description,
      body_html: body.contentBody,
      category: body.category,
      thumbnail_url: body.thumbnailUrl,
      read_time_value: body.readTimeValue || 5,
      tags: body.tags || [],
      status: body.status || 'draft',
      updated_at: new Date().toISOString()
    };

    const { data, error } = await supabaseAdmin
        .from('content')
        .upsert(dbPayload)
        .select();

    if (error) return res.status(500).json({ error: error.message });
    return res.status(200).json({ success: true, data });
  }

  return res.status(405).json({ error: 'Method not allowed' });
}

import { createClient } from '@supabase/supabase-js';

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // 1. Security Check
  const authHeader = req.headers.authorization;
  const secret = process.env.ADMIN_SECRET;
  if (!authHeader || !secret) return res.status(401).json({ error: 'Unauthorized' });

  try {
     const decoded = Buffer.from(authHeader.replace('Bearer ', ''), 'base64').toString();
     if (!decoded.startsWith(secret)) throw new Error('Invalid token');
  } catch(e) {
     return res.status(401).json({ error: 'Invalid Token' });
  }

  // 2. Setup Supabase Admin
  const supabaseUrl = process.env.SUPABASE_URL;
  const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!supabaseUrl || !supabaseServiceKey) {
     // Fallback for demo without DB
     return res.status(200).json({ 
        url: 'https://picsum.photos/800/600?random=' + Date.now(),
        mock: true 
     });
  }

  const supabase = createClient(supabaseUrl, supabaseServiceKey);

  // Note: Vercel Serverless handles body parsing automatically for JSON.
  // For binary file uploads in this simple setup, we expect a base64 string or
  // we use a client-side direct upload if we wanted to avoid server limits.
  // BUT the prompt asks for "/api/admin-upload".
  // We will assume the client sends JSON { fileName, fileType, fileBase64 } for simplicity 
  // to avoid multipart parsing complexity in a single file without middleware.

  const { fileName, fileBase64, fileType } = req.body;

  if (!fileName || !fileBase64) {
      return res.status(400).json({ error: 'Missing file data' });
  }

  const buffer = Buffer.from(fileBase64, 'base64');
  const path = `${Date.now()}_${fileName}`;

  const { data, error } = await supabase
    .storage
    .from('images')
    .upload(path, buffer, {
        contentType: fileType || 'image/jpeg',
        upsert: true
    });

  if (error) {
      return res.status(500).json({ error: error.message });
  }

  const { data: publicData } = supabase
    .storage
    .from('images')
    .getPublicUrl(path);

  return res.status(200).json({ url: publicData.publicUrl });
}

import { GoogleGenAI } from '@google/genai';

export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' });
  }

  // 1. Security Check
  const authHeader = req.headers.authorization;
  const secret = process.env.ADMIN_SECRET;

  if (!authHeader || !secret) {
      return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
      const decoded = Buffer.from(authHeader.replace('Bearer ', ''), 'base64').toString();
      if (!decoded.startsWith(secret)) {
          throw new Error('Invalid token');
      }
  } catch (e) {
      return res.status(401).json({ error: 'Invalid Token' });
  }

  // 2. Initialize Gemini
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: 'Gemini API Key missing' });
  }

  const { action, text } = req.body;
  const ai = new GoogleGenAI({ apiKey });

  // 3. Construct Prompt
  let prompt = "";

  switch (action) {
    case 'improve':
      prompt = `Rewrite the following text to be more engaging, professional, and clear. Keep the same meaning. \n\nText: "${text}"`;
      break;
    case 'summarize':
      prompt = `Summarize the following text into a concise paragraph. \n\nText: "${text}"`;
      break;
    case 'expand':
      prompt = `Expand the following text with more details, examples, and depth suitable for a blog post. \n\nText: "${text}"`;
      break;
    default:
      return res.status(400).json({ error: 'Invalid action' });
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return res.status(200).json({ result: response.text });
  } catch (error) {
    console.error('AI Error:', error);
    return res.status(500).json({ error: error.message });
  }
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { ContentItem } from '../types';
import { MOCK_CONTENT } from '../constants';

interface ContentContextType {
  content: ContentItem[];
  loading: boolean;
  refreshContent: () => Promise<void>;
}

const ContentContext = createContext<ContentContextType | undefined>(undefined);

export const ContentProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [content, setContent] = useState<ContentItem[]>(MOCK_CONTENT);
  const [loading, setLoading] = useState(true);

  const fetchContent = async () => {
    try {
      // Fetch from our API route which queries Supabase
      const res = await fetch('/api/content');
      if (res.ok) {
        const json = await res.json();
        if (json.data && json.data.length > 0) {
          // Merge API content. In a real app, you might replace MOCK entirely.
          // For safety/demo, we use API data if available.
          setContent(json.data);
        } else {
          // Keep MOCK_CONTENT if DB is empty or connection fails
          console.log('Using fallback/mock content');
        }
      }
    } catch (e) {
      console.error("Failed to fetch content, using mocks", e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchContent();
  }, []);

  return (
    <ContentContext.Provider value={{ content, loading, refreshContent: fetchContent }}>
      {children}
    </ContentContext.Provider>
  );
};

export const useContent = () => {
  const context = useContext(ContentContext);
  if (context === undefined) {
    throw new Error('useContent must be used within a ContentProvider');
  }
  return context;
};

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { AISuggestion, ContentItem, FeedbackSummary } from '../types';
import { useContent } from './ContentContext';

// --- Types ---
export interface ChatSettings {
  systemPrompt: string;
  suggestedQuestions: string[];
  isEnabled: boolean;
}

export interface UploadedImage {
  id: string;
  url: string;
  name: string;
  size: number;
  uploadedAt: string;
}

export interface SiteAppearance {
  fontFamily: string;
  baseFontSize: number;
  letterSpacing: number;
  lineHeight: number;
}

export interface SiteImages {
  [key: string]: string;
}

interface AdminContextType {
  isAuthenticated: boolean;
  login: (password: string) => Promise<boolean>;
  logout: () => void;
  token: string | null;

  // AI & Content
  aiSuggestions: AISuggestion[];
  generateDraftFromAI: (suggestionId: string) => Promise<ContentItem>;
  adminContent: ContentItem[];
  saveContent: (content: ContentItem) => Promise<boolean>;
  deleteContent: (id: string) => void;
  uploadImage: (file: File) => Promise<string | null>;

  // New AI Helper
  askAI: (action: string, text: string) => Promise<string>;

  feedbackSummary: FeedbackSummary;
  chatSettings: ChatSettings;
  updateChatSettings: (settings: ChatSettings) => void;
  uploadedImages: UploadedImage[];
  addImage: (image: UploadedImage) => void;
  deleteImage: (id: string) => void;
  siteAppearance: SiteAppearance;
  updateSiteAppearance: (appearance: SiteAppearance) => void;
  resetSiteAppearance: () => void;
  siteImages: SiteImages;
  updateSiteImage: (key: string, url: string) => void;
}

const AdminContext = createContext<AdminContextType | undefined>(undefined);

// Defaults & Mocks
const DEFAULT_APPEARANCE: SiteAppearance = { fontFamily: 'Inter', baseFontSize: 16, letterSpacing: 0, lineHeight: 1.6 };
const DEFAULT_CHAT_SETTINGS: ChatSettings = { systemPrompt: "You are a helpful assistant.", suggestedQuestions: ["Trend?", "News?"], isEnabled: true };

export const AdminProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const { content: globalContent, refreshContent } = useContent();

  // Auth State
  const [token, setToken] = useState<string | null>(() => {
      // Check local storage for persistence
      if (typeof window !== 'undefined') {
          return localStorage.getItem('cm_admin_token');
      }
      return null;
  });
  const [isAuthenticated, setIsAuthenticated] = useState(!!token);

  // Local Admin State
  const [aiSuggestions, setAiSuggestions] = useState<AISuggestion[]>([]); 
  const [chatSettings, setChatSettings] = useState<ChatSettings>(DEFAULT_CHAT_SETTINGS);
  const [uploadedImages, setUploadedImages] = useState<UploadedImage[]>([]);
  const [siteAppearance, setSiteAppearance] = useState<SiteAppearance>(DEFAULT_APPEARANCE);
  const [siteImages, setSiteImages] = useState<SiteImages>({});

  const login = async (password: string): Promise<boolean> => {
    try {
      const response = await fetch('/api/admin-login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ password })
      });
      const data = await response.json();
      if (data.success && data.token) {
        setIsAuthenticated(true);
        setToken(data.token);
        localStorage.setItem('cm_admin_auth', 'true');
        localStorage.setItem('cm_admin_token', data.token);
        return true;
      }
      return false;
    } catch (e) { return false; }
  };

  const logout = () => {
    setIsAuthenticated(false);
    setToken(null);
    localStorage.removeItem('cm_admin_auth');
    localStorage.removeItem('cm_admin_token');
  };

  const saveContent = async (contentItem: ContentItem): Promise<boolean> => {
    if (!token) return false;
    try {
      const res = await fetch('/api/content', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(contentItem)
      });
      if (res.ok) {
        await refreshContent(); // Refresh global context
        return true;
      }
      return false;
    } catch (e) {
      console.error(e);
      return false;
    }
  };

  const askAI = async (action: string, text: string): Promise<string> => {
    if (!token) return "Unauthorized";
    try {
      const res = await fetch('/api/admin-ai-content', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({ action, text })
      });
      const data = await res.json();
      return data.result || "No response";
    } catch (e) {
      return "AI Error";
    }
  };

  const uploadImage = async (file: File): Promise<string | null> => {
      if (!token) return null;
      try {
          // Convert file to base64
          const reader = new FileReader();
          return new Promise((resolve) => {
              reader.onload = async () => {
                  const base64 = (reader.result as string).split(',')[1];
                  const res = await fetch('/api/admin-upload', {
                      method: 'POST',
                      headers: {
                          'Content-Type': 'application/json',
                          'Authorization': `Bearer ${token}`
                      },
                      body: JSON.stringify({ 
                          fileName: file.name,
                          fileType: file.type,
                          fileBase64: base64
                      })
                  });
                  if (res.ok) {
                      const data = await res.json();
                      // Add to local gallery too
                      addImage({
                          id: Date.now().toString(),
                          url: data.url,
                          name: file.name,
                          size: file.size,
                          uploadedAt: new Date().toISOString()
                      });
                      resolve(data.url);
                  } else {
                      resolve(null);
                  }
              };
              reader.readAsDataURL(file);
          });
      } catch (e) {
          console.error(e);
          return null;
      }
  };

  // Mocks/Placeholders
  const generateDraftFromAI = async (id: string) => { 
      return { id: 'new', title: 'New', title_en: 'New', description: '', description_en: '', category: 'Tech', category_en: 'Tech', views: 0, publishedDate: '', readTime: '5', readTimeValue: 5, isVideo: false, tags: [], tags_en: [], thumbnailUrl: '' } as ContentItem; 
  };
  const deleteContent = (id: string) => { /* Implement delete via API later */ };
  const updateChatSettings = (s: ChatSettings) => setChatSettings(s);
  const addImage = (img: UploadedImage) => setUploadedImages(p => [img, ...p]);
  const deleteImage = (id: string) => setUploadedImages(p => p.filter(i => i.id !== id));
  const updateSiteAppearance = (a: SiteAppearance) => setSiteAppearance(a);
  const resetSiteAppearance = () => setSiteAppearance(DEFAULT_APPEARANCE);
  const updateSiteImage = (k: string, v: string) => setSiteImages(p => ({...p, [k]: v}));

  // Load persisted local settings
  useEffect(() => {
    const savedImg = localStorage.getItem('cm_admin_images');
    if (savedImg) setUploadedImages(JSON.parse(savedImg));
    const savedApp = localStorage.getItem('cm_site_appearance');
    if (savedApp) setSiteAppearance(JSON.parse(savedApp));
  }, []);

  return (
    <AdminContext.Provider value={{
      isAuthenticated, login, logout, token,
      adminContent: globalContent,
      saveContent, deleteContent, uploadImage,
      aiSuggestions, generateDraftFromAI,
      askAI,
      feedbackSummary: { totalRatings: 0, averageRating: 0, topRequestedTopics: [] },
      chatSettings, updateChatSettings,
      uploadedImages, addImage, deleteImage,
      siteAppearance, updateSiteAppearance, resetSiteAppearance,
      siteImages, updateSiteImage: updateSiteImage
    }}>
      {children}
    </AdminContext.Provider>
  );
};

export const useAdmin = () => {
  const context = useContext(AdminContext);
  if (context === undefined) throw new Error('useAdmin must be used within an AdminProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useAdmin } from '../../context/AdminContext';
import { Save, ArrowLeft, Image as ImageIcon, Sparkles, Wand2, UploadCloud, RefreshCw, Type, List, Quote } from 'lucide-react';
import { CATEGORIES } from '../../constants';
import { ContentItem } from '../../types';

export const AdminEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { adminContent, saveContent, askAI, uploadImage } = useAdmin();

  const [formData, setFormData] = useState<Partial<ContentItem>>({});
  const [loading, setLoading] = useState(true);
  const [aiLoading, setAiLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (id) {
       const found = adminContent.find(c => c.id === id);
       if (found) {
          setFormData(JSON.parse(JSON.stringify(found)));
       } else if (id === 'new') {
          setFormData({
              id: `draft-${Date.now()}`,
              status: 'draft',
              views: 0,
              readTimeValue: 5,
              isVideo: false,
              tags: [], tags_en: []
          });
       }
    }
    setLoading(false);
  }, [id, adminContent]);

  const handleChange = (field: keyof ContentItem, value: any) => {
     setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async (status: 'published' | 'draft') => {
     if (formData.id) {
        const success = await saveContent({
           ...formData as ContentItem,
           status: status,
           publishedDate: status === 'published' ? new Date().toISOString().split('T')[0] : formData.publishedDate || ''
        });
        if (success) {
            navigate('/admin/content');
        } else {
            alert('Failed to save. Check network or auth.');
        }
     }
  };

  const handleAI = async (action: string, targetField: 'contentBody' | 'description') => {
      const text = formData[targetField] as string;
      if (!text) return alert('Please enter some text first.');

      setAiLoading(true);
      const result = await askAI(action, text);
      setAiLoading(false);

      if (result && result !== "AI Error") {
          if (confirm('AI Suggestion:\n\n' + result + '\n\nApply?')) {
              handleChange(targetField, result);
          }
      } else {
          alert('AI request failed.');
      }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          setUploading(true);
          const url = await uploadImage(e.target.files[0]);
          setUploading(false);
          if (url) {
              handleChange('thumbnailUrl', url);
          } else {
              alert('Upload failed');
          }
      }
  };

  // Simple Rich Text Insert
  const insertTag = (tag: string) => {
      const textarea = document.getElementById('bodyEditor') as HTMLTextAreaElement;
      if (!textarea) return;

      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const text = textarea.value;
      const before = text.substring(0, start);
      const after = text.substring(end, text.length);
      const selection = text.substring(start, end);

      let newText = '';
      if (tag === 'b') newText = `<b>${selection}</b>`;
      if (tag === 'i') newText = `<i>${selection}</i>`;
      if (tag === 'h2') newText = `<h2>${selection}</h2>`;
      if (tag === 'ul') newText = `<ul>\n<li>${selection}</li>\n</ul>`;

      handleChange('contentBody', before + newText + after);
  };

  if (loading) return <div className="p-8 text-white">Loading...</div>;
  if (!formData.id) return <div className="p-8 text-white">Content not found</div>;

  return (
