             >
                Save Draft
             </button>
             <button 
               onClick={() => handleSave('published')}
               className="px-6 py-2 bg-gradient-brand text-white rounded-lg font-bold text-sm shadow-glow hover:opacity-90 transition-opacity flex items-center gap-2"
             >
                <Save size={16} />
                Publish
             </button>
