          </div>

          <div className="prose prose-lg prose-gray dark:prose-invert max-w-none text-text-main">
             {/* Description Intro */}
             <p className="font-medium text-xl text-text-main mb-6 leading-relaxed border-l-4 border-primary-500 pl-4">
