                />
                <SearchIcon className="absolute left-5 top-1/2 transform -translate-y-1/2 text-text-muted group-focus-within:text-primary-500 transition-colors" size={24} />
            </div>
        </div>

        {searchTerm && (
            <div>
                <h2 className="text-lg font-bold text-text-main mb-8 pb-4 border-b border-border">
