export const AdminEditor: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { adminContent, saveContent, askAI, uploadImage } = useAdmin();

  const [formData, setFormData] = useState<Partial<ContentItem>>({});
  const [loading, setLoading] = useState(true);
  const [aiLoading, setAiLoading] = useState(false);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    if (id) {
       const found = adminContent.find(c => c.id === id);
       if (found) {
          setFormData(JSON.parse(JSON.stringify(found)));
       } else if (id === 'new') {
          setFormData({
              id: `draft-${Date.now()}`,
              status: 'draft',
              views: 0,
              readTimeValue: 5,
              isVideo: false,
              tags: [], tags_en: []
          });
       }
    }
    setLoading(false);
  }, [id, adminContent]);

  const handleChange = (field: keyof ContentItem, value: any) => {
     setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleSave = async (status: 'published' | 'draft') => {
     if (formData.id) {
        const success = await saveContent({
           ...formData as ContentItem,
           status: status,
           publishedDate: status === 'published' ? new Date().toISOString().split('T')[0] : formData.publishedDate || ''
        });
        if (success) {
            navigate('/admin/content');
        } else {
            alert('Failed to save. Check network or auth.');
        }
     }
  };

  const handleAI = async (action: string, targetField: 'contentBody' | 'description') => {
      const text = formData[targetField] as string;
      if (!text) return alert('Please enter some text first.');

      setAiLoading(true);
      const result = await askAI(action, text);
      setAiLoading(false);

      if (result && result !== "AI Error") {
          if (confirm('AI Suggestion:\n\n' + result + '\n\nApply?')) {
              handleChange(targetField, result);
          }
      } else {
          alert('AI request failed.');
      }
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0]) {
          setUploading(true);
          const url = await uploadImage(e.target.files[0]);
          setUploading(false);
          if (url) {
              handleChange('thumbnailUrl', url);
          } else {
              alert('Upload failed');
          }
      }
  };

  // Simple Rich Text Insert
  const insertTag = (tag: string) => {
      const textarea = document.getElementById('bodyEditor') as HTMLTextAreaElement;
      if (!textarea) return;

      const start = textarea.selectionStart;
      const end = textarea.selectionEnd;
      const text = textarea.value;
      const before = text.substring(0, start);
      const after = text.substring(end, text.length);
      const selection = text.substring(start, end);

      let newText = '';
      if (tag === 'b') newText = `<b>${selection}</b>`;
      if (tag === 'i') newText = `<i>${selection}</i>`;
      if (tag === 'h2') newText = `<h2>${selection}</h2>`;
      if (tag === 'ul') newText = `<ul>\n<li>${selection}</li>\n</ul>`;

      handleChange('contentBody', before + newText + after);
  };

  if (loading) return <div className="p-8 text-white">Loading...</div>;
  if (!formData.id) return <div className="p-8 text-white">Content not found</div>;

  return (
    <div className="max-w-6xl mx-auto pb-20">
       {/* Toolbar */}
       <div className="flex items-center justify-between mb-8 sticky top-0 bg-[#0F172A]/95 backdrop-blur-md py-4 z-40 border-b border-white/5">
          <div className="flex items-center gap-4">
             <button onClick={() => navigate('/admin/content')} className="p-2 hover:bg-white/10 rounded-lg text-slate-400 hover:text-white">
                <ArrowLeft size={20} />
             </button>
             <div>
                <h1 className="text-xl font-bold text-white">
                   {formData.status === 'draft' ? 'Draft Editor' : 'Edit Article'}
                </h1>
                <span className="text-xs text-slate-500">ID: {formData.id}</span>
             </div>
          </div>
          <div className="flex items-center gap-3">
             <button 
               onClick={() => handleSave('draft')}
               className="px-4 py-2 bg-white/5 hover:bg-white/10 text-white rounded-lg font-medium text-sm transition-colors"
             >
                Save Draft
             </button>
             <button 
               onClick={() => handleSave('published')}
               className="px-6 py-2 bg-gradient-brand text-white rounded-lg font-bold text-sm shadow-glow hover:opacity-90 transition-opacity flex items-center gap-2"
             >
                <Save size={16} />
                Publish
             </button>
          </div>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

          {/* Main Editor */}
          <div className="lg:col-span-2 space-y-6">

             {/* Title */}
             <div className="bg-[#1E293B] p-6 rounded-xl border border-white/5 group relative">
                <label className="block text-slate-400 text-xs font-bold mb-2 uppercase tracking-wider">Title</label>
                <input 
                   type="text" 
                   value={formData.title || ''} 
                   onChange={(e) => handleChange('title', e.target.value)}
                   className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-4 py-3 text-white font-bold text-lg focus:border-brand-purple outline-none"
                   placeholder="Enter article title..."
                />
             </div>

             {/* Description with AI */}
             <div className="bg-[#1E293B] p-6 rounded-xl border border-white/5 group relative">
                <div className="flex justify-between mb-2">
                    <label className="block text-slate-400 text-xs font-bold uppercase tracking-wider">Description</label>
                    <div className="flex gap-2">
                        <button onClick={() => handleAI('improve', 'description')} className="text-brand-purple hover:text-white text-xs flex items-center gap-1 transition-colors">
                            <Sparkles size={12} /> Improve
                        </button>
                        <button onClick={() => handleAI('summarize', 'description')} className="text-brand-purple hover:text-white text-xs flex items-center gap-1 transition-colors">
                            <Wand2 size={12} /> Summarize
                        </button>
                    </div>
                </div>
                <textarea 
                   rows={3}
                   value={formData.description || ''} 
                   onChange={(e) => handleChange('description', e.target.value)}
                   className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-4 py-3 text-slate-300 focus:border-brand-purple outline-none resize-none"
                   placeholder="Short summary for SEO and cards..."
                />
             </div>

             {/* Body Editor */}
             <div className="bg-[#1E293B] p-6 rounded-xl border border-white/5 min-h-[500px] group relative">
                <div className="flex justify-between mb-4">
                    <div className="flex items-center gap-2">
                        <label className="block text-slate-400 text-xs font-bold uppercase tracking-wider">Content Body (HTML)</label>
                        <div className="h-4 w-[1px] bg-white/10 mx-2"></div>
                        <button onClick={() => insertTag('b')} className="p-1 hover:bg-white/10 rounded" title="Bold"><strong className="text-white">B</strong></button>
                        <button onClick={() => insertTag('i')} className="p-1 hover:bg-white/10 rounded" title="Italic"><em className="text-white">I</em></button>
                        <button onClick={() => insertTag('h2')} className="p-1 hover:bg-white/10 rounded" title="Header"><Type size={14} className="text-white"/></button>
                        <button onClick={() => insertTag('ul')} className="p-1 hover:bg-white/10 rounded" title="List"><List size={14} className="text-white"/></button>
                    </div>
                    <div className="flex gap-2">
                         <button onClick={() => handleAI('expand', 'contentBody')} className="text-brand-purple hover:text-white text-xs flex items-center gap-1 transition-colors">
                            <Wand2 size={12} /> Expand
                        </button>
                        <button onClick={() => handleAI('improve', 'contentBody')} className="text-brand-purple hover:text-white text-xs flex items-center gap-1 transition-colors">
                            <Sparkles size={12} /> Improve
                        </button>
                    </div>
                </div>
                <textarea 
                   id="bodyEditor"
                   value={formData.contentBody || ''} 
                   onChange={(e) => handleChange('contentBody', e.target.value)}
                   className="w-full h-[600px] bg-[#0F172A] border border-white/10 rounded-lg px-4 py-4 text-slate-300 font-mono text-sm focus:border-brand-purple outline-none leading-relaxed"
                   placeholder="Write content here. HTML tags allowed (<b>, <i>, <p>)..."
                />
             </div>

          </div>

          {/* Sidebar Settings */}
          <div className="space-y-6">

             <div className="bg-[#1E293B] p-6 rounded-xl border border-white/5 space-y-4">
                <h3 className="font-bold text-white">Settings</h3>

                {/* Category */}
                <div>
                  <label className="block text-slate-400 text-xs font-bold mb-2">Category</label>
                  <select 
                     value={formData.category || ''}
                     onChange={(e) => handleChange('category', e.target.value)}
                     className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-3 py-2 text-white text-sm outline-none"
                  >
                     <option value="">Select...</option>
                     {CATEGORIES.map(cat => (
                        <option key={cat.id} value={cat.label}>{cat.label}</option>
                     ))}
                  </select>
                </div>

                {/* Read Time */}
                <div>
                   <label className="block text-slate-400 text-xs font-bold mb-2">Read Time (min)</label>
                   <input 
                      type="number" 
                      value={formData.readTimeValue || 5} 
                      onChange={(e) => handleChange('readTimeValue', parseInt(e.target.value))}
                      className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-3 py-2 text-white text-sm outline-none"
                   />
                </div>

                {/* Tags */}
                <div>
                   <label className="block text-slate-400 text-xs font-bold mb-2">Tags (comma separated)</label>
                   <input 
                      type="text" 
                      value={formData.tags?.join(', ') || ''} 
                      onChange={(e) => handleChange('tags', e.target.value.split(',').map(t => t.trim()))}
                      className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-3 py-2 text-white text-sm outline-none"
                   />
                </div>

             </div>

             {/* Image Upload */}
             <div className="bg-[#1E293B] p-6 rounded-xl border border-white/5 space-y-4">
                <h3 className="font-bold text-white">Thumbnail</h3>
                <div className="relative aspect-video bg-[#0F172A] rounded-lg border border-white/10 overflow-hidden flex items-center justify-center group">
                    {formData.thumbnailUrl ? (
                        <img src={formData.thumbnailUrl} alt="Thumb" className="w-full h-full object-cover" />
                    ) : (
                        <ImageIcon className="text-slate-600" />
                    )}
                    <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                        <label className="cursor-pointer px-3 py-1 bg-white text-black rounded-lg text-xs font-bold flex items-center gap-1">
                            <UploadCloud size={12} />
                            {uploading ? 'Uploading...' : 'Replace'}
                            <input type="file" className="hidden" onChange={handleImageUpload} accept="image/*" />
                        </label>
                    </div>
                </div>
                <input 
                   type="text" 
                   value={formData.thumbnailUrl || ''} 
                   onChange={(e) => handleChange('thumbnailUrl', e.target.value)}
                   className="w-full bg-[#0F172A] border border-white/10 rounded-lg px-3 py-2 text-white text-xs outline-none"
                   placeholder="https://..."
                />
             </div>

             {/* AI Status */}
             {aiLoading && (
                 <div className="p-4 bg-brand-purple/20 border border-brand-purple/50 rounded-xl flex items-center gap-3 animate-pulse">
                     <RefreshCw size={20} className="animate-spin text-brand-purple" />
                     <span className="text-white text-sm font-bold">AI Processing...</span>
                 </div>
             )}

          </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Menu, X, Search, User, Moon, Sun, ShieldCheck } from 'lucide-react';
import * as ReactRouterDOM from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { useTheme } from '../context/ThemeContext';
import { useAdmin } from '../context/AdminContext';
import { CATEGORIES } from '../constants';
import { Container } from './ui/Container';

const { Link, NavLink, useNavigate } = ReactRouterDOM;

export const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [scrolled, setScrolled] = useState(false);
  const navigate = useNavigate();
  const { t, language, setLanguage } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const { isAuthenticated } = useAdmin();

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Close mobile menu on ESC
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setIsOpen(false);
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  // Lock body scroll when menu is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchValue.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchValue)}`);
      setIsOpen(false);
    }
  };

  const handleClearSearch = () => {
    setSearchValue('');
  };

  const handleAdminClick = () => {
    navigate('/admin');
    setIsOpen(false);
  };

  const mainNavItems = [
    { label: t('nav_home'), path: '/', type: 'link' },
    ...CATEGORIES.map(cat => ({
       label: cat.label,
       path: `/${cat.slug}`, 
       type: 'category'
    })),
    { label: t('nav_video'), path: '/video', type: 'link' }
  ];

  return (
    <nav 
      className={`sticky top-0 z-[100] w-full transition-all duration-300 ${
        scrolled ? 'glass shadow-sm' : 'bg-background border-b border-transparent'
      }`}
    >
      <div className="relative z-10">
        {/* TOP ROW: Brand, Search, Utilities */}
        <Container>
          <div className="flex h-16 items-center justify-between gap-6">

            {/* Logo */}
            <Link to="/" className="flex-shrink-0 flex items-center gap-2 group">
              <span className="font-bold text-xl md:text-2xl tracking-tight text-gradient transition-all duration-300 group-hover:opacity-90">
                Channel Mongolia
              </span>
            </Link>

            {/* Search Bar (Desktop) - COMPACT UI */}
            <div className="hidden md:flex flex-1 max-w-sm mx-auto">
              <form onSubmit={handleSearch} className="w-full relative group">
                  <div className="relative flex items-center">
                    <Search 
                      size={16} 
                      className="absolute left-3.5 text-text-muted group-focus-within:text-brand-purple transition-colors pointer-events-none" 
                    />
                    <input 
                      type="text" 
                      value={searchValue}
                      onChange={(e) => setSearchValue(e.target.value)}
                      placeholder={t('search_placeholder')}
                      className="w-full h-10 pl-10 pr-9 text-sm rounded-full bg-surfaceHighlight/50 border border-transparent hover:border-border/50 hover:bg-surfaceHighlight focus:bg-surface focus:border-brand-purple/50 focus:ring-2 focus:ring-brand-purple/10 text-text-main placeholder-text-muted outline-none transition-all duration-200"
                      aria-label="Search"
                    />
                    {searchValue && (
                      <button
                        type="button"
                        onClick={handleClearSearch}
                        className="absolute right-2.5 p-0.5 rounded-full text-text-muted hover:text-text-main hover:bg-black/5 dark:hover:bg-white/10 transition-colors"
                        aria-label="Clear search"
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
              </form>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-3">
              {/* Language */}
              <button 
                onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
                className="hidden sm:flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-surfaceHighlight transition-colors text-text-muted hover:text-text-main"
              >
                <span className={language === 'mn' ? 'text-brand-purple' : ''}>MN</span>
                <span className="opacity-30 mx-1">/</span>
                <span className={language === 'en' ? 'text-brand-purple' : ''}>EN</span>
              </button>

              {/* Theme Toggle (Desktop) */}
              <button
                onClick={toggleTheme}
                className="p-2 rounded-full text-text-muted hover:bg-surfaceHighlight hover:text-brand-orange transition-colors"
                aria-label={theme === 'dark' ? t('theme_light') : t('theme_dark')}
                title={theme === 'dark' ? t('theme_light') : t('theme_dark')}
              >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
              </button>

              {/* Admin */}
              <button 
                onClick={handleAdminClick}
                className={`hidden md:flex items-center gap-2 px-5 py-2 rounded-full text-sm font-semibold transition-all hover:-translate-y-0.5 ${
                  isAuthenticated 
                    ? 'bg-surfaceHighlight text-text-main border border-border hover:border-brand-purple/30' 
                    : 'bg-gradient-brand text-white shadow-glow hover:shadow-lg'
                }`}
              >
                {isAuthenticated ? <ShieldCheck size={18} /> : <User size={18} />}
                <span>{isAuthenticated ? 'Admin Panel' : t('login')}</span>
              </button>

              {/* Mobile Menu Toggle */}
              <button
                onClick={() => setIsOpen(true)}
                className="lg:hidden p-2 rounded-md text-text-main hover:bg-surfaceHighlight focus:outline-none"
                aria-label="Open menu"
              >
                <Menu size={24} />
              </button>
            </div>
          </div>
        </Container>

        {/* BOTTOM ROW: Navigation (Desktop) */}
        <div className="hidden lg:block border-t border-border/50">
          <Container>
            <div className="flex items-center h-12 gap-1 overflow-x-auto no-scrollbar">
              {mainNavItems.map((item) => (
                <NavLink
                  key={item.label}
                  to={item.path}
                  className={({ isActive }) => `
                    px-4 py-1.5 text-sm font-medium rounded-full whitespace-nowrap transition-all duration-200
                    ${isActive 
                      ? 'bg-brand-purple/10 text-brand-purple font-semibold' 
                      : 'text-text-muted hover:text-text-main hover:bg-surfaceHighlight'
                    }
                  `}
                >
                  {item.label}
                </NavLink>
              ))}
            </div>
          </Container>
        </div>
      </div>

      {/* Mobile Menu Backdrop */}
      {isOpen && (
        <div 
          className="fixed inset-0 z-[140] bg-black/50 backdrop-blur-sm animate-in fade-in duration-200"
          onClick={() => setIsOpen(false)}
        />
      )}

      {/* Mobile Menu Drawer */}
      <div 
        className={`fixed inset-y-0 right-0 z-[150] w-[85vw] max-w-sm bg-surface shadow-2xl transform transition-transform duration-300 ease-in-out ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <div className="flex flex-col h-full">
          <div className="flex items-center justify-between p-4 border-b border-border">
            <span className="font-bold text-xl text-gradient">Menu</span>
            <button 
              onClick={() => setIsOpen(false)} 
              className="p-2 text-text-muted hover:text-text-main rounded-full hover:bg-surfaceHighlight"
            >
              <X size={24} />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto px-4 py-6 space-y-6">

            {/* Mobile Search - COMPACT UI */}
            <form onSubmit={handleSearch} className="relative group">
               <div className="relative flex items-center">
                  <Search size={18} className="absolute left-4 text-text-muted group-focus-within:text-brand-purple transition-colors pointer-events-none" />
                  <input 
                    type="text" 
                    value={searchValue}
                    onChange={(e) => setSearchValue(e.target.value)}
                    placeholder={t('search_placeholder')}
                    className="w-full h-12 pl-12 pr-10 text-base rounded-2xl bg-surfaceHighlight border border-transparent focus:bg-surface focus:border-brand-purple/50 focus:ring-2 focus:ring-brand-purple/10 text-text-main placeholder-text-muted outline-none transition-all duration-200"
                    aria-label="Search"
                  />
                  {searchValue && (
                    <button
                      type="button"
                      onClick={handleClearSearch}
                      className="absolute right-3.5 p-1 rounded-full text-text-muted hover:text-text-main hover:bg-black/5 dark:hover:bg-white/10 transition-colors"
                    >
                      <X size={18} />
                    </button>
                  )}
               </div>
            </form>

            <nav className="space-y-1">
              {mainNavItems.map((item) => (
                <NavLink
                  key={item.label}
                  to={item.path}
                  onClick={() => setIsOpen(false)}
                  className={({ isActive }) => `
                    block px-4 py-3 rounded-xl text-base font-medium transition-all
                    ${isActive 
                      ? 'bg-brand-purple/10 text-brand-purple border-l-4 border-brand-purple' 
                      : 'text-text-main hover:bg-surfaceHighlight'
                    }
                  `}
                >
                  {item.label}
                </NavLink>
              ))}
            </nav>

            <div className="border-t border-border pt-4 space-y-2">
               <Link to="/bidnii-tukhai" onClick={() => setIsOpen(false)} className="block px-4 py-3 text-text-muted hover:text-text-main">{t('nav_about')}</Link>
               <Link to="/holboo-barikh" onClick={() => setIsOpen(false)} className="block px-4 py-3 text-text-muted hover:text-text-main">{t('contact')}</Link>
            </div>
          </div>

          <div className="p-4 border-t border-border bg-surfaceHighlight/50 space-y-3">
             {/* Mobile Theme & Lang Toggles */}
             <div className="flex items-center justify-between gap-2 mb-2">
                <button 
                  onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
                  className="flex-1 py-2 rounded-lg border border-border bg-surface text-text-muted text-xs font-bold hover:text-text-main transition-colors"
                >
                  {language === 'mn' ? 'EN хэл рүү шилжих' : 'Switch to Mongolian'}
                </button>
                <button
                  onClick={toggleTheme}
                  className="p-2 rounded-lg border border-border bg-surface text-text-muted hover:text-brand-orange transition-colors"
                  aria-label={t('theme_dark')}
                >
                   {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
                </button>
             </div>

             <button 
                onClick={handleAdminClick} 
                className={`w-full flex items-center justify-center gap-2 px-4 py-3 rounded-xl text-sm font-bold shadow-sm transition-transform active:scale-95 ${isAuthenticated ? 'bg-surface text-text-main border border-border' : 'bg-gradient-brand text-white'}`}
             >
                {isAuthenticated ? <ShieldCheck size={18} /> : <User size={18} />}
                <span>{isAuthenticated ? 'Admin Panel' : t('login')}</span>
              </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

import React, { useState, useEffect } from 'react';
import { Search as SearchIcon, X } from 'lucide-react';
import { useContent } from '../context/ContentContext';
import { KnowledgeCard } from '../components/KnowledgeCard';
import * as ReactRouterDOM from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';

const { useSearchParams } = ReactRouterDOM;

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [searchTerm, setSearchTerm] = useState(query);
  const { t, language } = useLanguage();
  const { content } = useContent(); // Dynamic
  const isEn = language === 'en';

  useEffect(() => {
    setSearchTerm(query);
  }, [query]);

  const filtered = searchTerm 
    ? content.filter(c => {
        const title = isEn ? c.title_en : c.title;
        const desc = isEn ? c.description_en : c.description;
        return (title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
               (desc || '').toLowerCase().includes(searchTerm.toLowerCase());
      })
    : [];

  const handleClear = () => setSearchTerm('');

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 min-h-[60vh]">
