import React, { useState } from 'react';
import { CATEGORIES } from '../constants';
import { useContent } from '../context/ContentContext';
import { KnowledgeCard } from '../components/KnowledgeCard';
import { Filter, Grid, List as ListIcon, FolderOpen } from 'lucide-react';
import { useLanguage } from '../context/LanguageContext';
import * as ReactRouterDOM from 'react-router-dom';

const { useNavigate } = ReactRouterDOM;

interface CategoriesPageProps {
    categorySlug?: string;
    filter?: string; 
}

export const CategoriesPage: React.FC<CategoriesPageProps> = ({ categorySlug, filter }) => {
  const { t, language } = useLanguage();
  const navigate = useNavigate();
  const { content } = useContent(); // Dynamic Content
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const activeSlug = categorySlug || filter || 'all';

  const handleFilterChange = (slug: string) => {
    if (slug === 'all') navigate('/categories');
    else navigate(`/${slug}`);
  };

  const activeCategoryLabel = (() => {
      if (activeSlug === 'all') return t('all_knowledge');
      if (activeSlug === 'video') return t('video_knowledge');
      return CATEGORIES.find(c => c.slug === activeSlug)?.label || t('nav_categories');
  })();

  const filteredContent = (() => {
      if (activeSlug === 'all') return content;
      if (activeSlug === 'video') return content.filter(c => c.isVideo);

      const catObj = CATEGORIES.find(cat => cat.slug === activeSlug);
      return catObj 
         ? content.filter(c => c.category === catObj.label || c.category_en === catObj.label_en)
         : content;
  })();

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">

      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <h1 className="text-3xl font-extrabold text-text-main drop-shadow-sm dark:drop-shadow-md">
          {activeCategoryLabel}
        </h1>

        <div className="flex items-center gap-3">
            <span className="text-sm text-text-muted font-medium hidden sm:block">{t('sort_by')}</span>
            <button className="flex items-center gap-2 px-4 py-2 bg-surface border border-border rounded-lg text-sm font-medium hover:bg-surfaceHighlight text-text-main transition-colors focus-visible:ring-2 ring-brand-purple">
                <Filter size={16} />
                <span>{t('newest')}</span>
            </button>
            <div className="h-6 w-px bg-border mx-1 hidden sm:block"></div>
            <div className="hidden sm:flex bg-surface border border-border rounded-lg p-1">
               <button onClick={() => setViewMode('grid')} className={`p-1.5 rounded ${viewMode === 'grid' ? 'bg-surfaceHighlight text-brand-purple' : 'text-text-muted hover:text-text-main'}`}>
                  <Grid size={16} />
               </button>
               <button onClick={() => setViewMode('list')} className={`p-1.5 rounded ${viewMode === 'list' ? 'bg-surfaceHighlight text-brand-purple' : 'text-text-muted hover:text-text-main'}`}>
                  <ListIcon size={16} />
               </button>
            </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">

        <div className="lg:col-span-1">
            <div className="bg-surface p-4 rounded-xl shadow-sm border border-border sticky top-24">
                <h3 className="font-bold text-text-main mb-4 px-2 text-xs uppercase tracking-wider opacity-70">{t('nav_categories')}</h3>
                <div className="space-y-1">
                    <button
                        onClick={() => handleFilterChange('all')}
                        className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                            activeSlug === 'all' 
                            ? 'bg-brand-purple text-white shadow-md' 
                            : 'text-text-muted hover:bg-surfaceHighlight hover:text-text-main'
                        }`}
                    >
                        {t('all_knowledge')}
                    </button>
                    {CATEGORIES.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => handleFilterChange(cat.slug)}
                            className={`w-full text-left px-3 py-2.5 rounded-lg text-sm font-medium transition-all ${
                                activeSlug === cat.slug 
                                ? 'bg-brand-purple text-white shadow-md' 
                                : 'text-text-muted hover:bg-surfaceHighlight hover:text-text-main'
                            }`}
                        >
                            {cat.label}
                        </button>
                    ))}
                </div>
            </div>
        </div>

        <div className="lg:col-span-3">
            {filteredContent.length > 0 ? (
                <div className={`grid gap-8 ${viewMode === 'grid' ? 'grid-cols-1 md:grid-cols-2 lg:grid-cols-2' : 'grid-cols-1'}`}>
                    {filteredContent.map(item => (
                        <KnowledgeCard key={item.id} item={item} />
                    ))}
                </div>
            ) : (
                <div className="py-24 text-center bg-surface rounded-2xl border border-dashed border-border flex flex-col items-center justify-center">
                    <div className="w-16 h-16 bg-surfaceHighlight rounded-full flex items-center justify-center text-text-muted mb-4">
                       <FolderOpen size={32} />
                    </div>
                    <h3 className="text-lg font-bold text-text-main mb-1">Хоосон байна</h3>
                    <p className="text-text-muted max-w-sm mx-auto">{t('no_results')}</p>
                </div>
            )}
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Search as SearchIcon, X, FileSearch } from 'lucide-react';
import { useContent } from '../context/ContentContext';
import { KnowledgeCard } from '../components/KnowledgeCard';
import * as ReactRouterDOM from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';

const { useSearchParams } = ReactRouterDOM;

export const SearchPage: React.FC = () => {
  const [searchParams] = useSearchParams();
  const query = searchParams.get('q') || '';
  const [searchTerm, setSearchTerm] = useState(query);
  const { t, language } = useLanguage();
  const { content } = useContent(); // Dynamic
  const isEn = language === 'en';

  useEffect(() => {
    setSearchTerm(query);
  }, [query]);

  const filtered = searchTerm 
    ? content.filter(c => {
        const title = isEn ? c.title_en : c.title;
        const desc = isEn ? c.description_en : c.description;
        return (title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
               (desc || '').toLowerCase().includes(searchTerm.toLowerCase());
      })
    : [];

  const handleClear = () => setSearchTerm('');

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-16 min-h-[60vh]">
        <div className="max-w-2xl mx-auto mb-16">
            <h1 className="text-3xl font-bold text-center text-text-main mb-8 drop-shadow-sm dark:drop-shadow-md">{t('search_placeholder')}</h1>

            {/* HERO SEARCH BAR - INTEGRATED UI */}
            <div className="relative group">
                <SearchIcon className="absolute left-5 top-1/2 transform -translate-y-1/2 text-slate-400 pointer-events-none" size={24} />
                <input
                    type="text"
                    placeholder={t('search_placeholder')}
                    className="w-full h-14 pl-12 pr-12 rounded-full border border-border bg-white/50 dark:bg-white/5 backdrop-blur-sm focus:bg-white dark:focus:bg-slate-900 focus:border-brand-purple/50 focus:ring-4 focus:ring-brand-purple/10 outline-none text-lg text-text-main placeholder-slate-400 shadow-sm hover:shadow-md transition-all duration-300"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    autoFocus
                />
                {searchTerm && (
                    <button 
                        onClick={handleClear}
                        className="absolute right-4 top-1/2 transform -translate-y-1/2 p-2 rounded-full text-slate-400 hover:text-text-main hover:bg-surfaceHighlight transition-colors"
                        aria-label="Clear search"
                    >
                        <X size={20} />
                    </button>
                )}
            </div>
        </div>

        {searchTerm && (
            <div>
                <h2 className="text-lg font-bold text-text-main mb-8 pb-4 border-b border-border flex items-center justify-between">
                    <span>{t('search_results')}</span>
                    <span className="px-3 py-1 bg-surfaceHighlight rounded-full text-xs font-bold text-text-muted">{filtered.length} items</span>
                </h2>

                {filtered.length > 0 ? (
                   <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                       {filtered.map(item => (
                           <KnowledgeCard key={item.id} item={item} />
                       ))}
                   </div>
                ) : (
                    <div className="text-center py-20 bg-surface rounded-2xl border border-dashed border-border flex flex-col items-center justify-center">
                         <div className="w-16 h-16 bg-surfaceHighlight rounded-full flex items-center justify-center text-text-muted mb-4">
                            <FileSearch size={32} />
                         </div>
                         <h3 className="text-lg font-bold text-text-main mb-2">Хайлт илэрцгүй</h3>
                         <p className="text-text-muted">{t('no_results')}</p>
                    </div>
                )}
            </div>
        )}

        {!searchTerm && (
            <div className="text-center mt-20 opacity-50">
                 <p className="text-text-muted text-sm font-medium tracking-widest uppercase">Channel Mongolia</p>
            </div>
        )}
    </div>
  );
};

import React, { useState } from 'react';
import { Image as ImageIcon } from 'lucide-react';

interface ThumbnailProps {
  src: string;
  alt: string;
  className?: string;
  aspectRatio?: 'video' | 'square' | 'wide';
  showOverlay?: boolean;
  overlayContent?: React.ReactNode;
}

export const Thumbnail: React.FC<ThumbnailProps> = ({ 
  src, 
  alt, 
  className = '', 
  aspectRatio = 'video',
  showOverlay = true,
  overlayContent 
}) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [hasError, setHasError] = useState(false);

  // Exact aspect ratio enforcement for consistency
  const aspectClasses = {
    video: 'aspect-[16/9]',
    square: 'aspect-square',
    wide: 'aspect-[21/9]'
  };

  return (
    <div className={`relative overflow-hidden bg-surfaceHighlight w-full ${aspectClasses[aspectRatio]} ${className}`}>
      {/* Skeleton / Loading State */}
      <div className={`absolute inset-0 bg-gray-200 dark:bg-gray-800 flex items-center justify-center transition-opacity duration-500 ${isLoaded ? 'opacity-0' : 'opacity-100'}`}>
         {!hasError && <ImageIcon className="text-gray-300 dark:text-gray-600 w-8 h-8 animate-pulse" />}
      </div>

      {/* Actual Image */}
      {!hasError ? (
        <img 
          src={src} 
          alt={alt} 
          loading="lazy"
          className={`w-full h-full object-cover transition-all duration-700 ${isLoaded ? 'opacity-100 blur-0 scale-100' : 'opacity-0 blur-xl scale-110'}`}
          onLoad={() => setIsLoaded(true)}
          onError={() => setHasError(true)}
        />
      ) : (
        <div className="absolute inset-0 flex items-center justify-center bg-surfaceHighlight text-text-muted text-sm flex-col gap-2">
           <ImageIcon size={20} className="opacity-50" />
           <span className="text-xs">Unavailable</span>
        </div>
      )}

      {/* Subtle Gradient Overlay - Adjusted to be lighter/more transparent for better Light Mode look */}
      {showOverlay && (
        <div className="absolute inset-0 bg-gradient-to-t from-black/40 via-black/10 to-transparent pointer-events-none mix-blend-multiply"></div>
      )}

      {/* Overlay Content (e.g., play button, tags) */}
      {overlayContent && (
        <div className="absolute inset-0 z-10 pointer-events-none">
          {overlayContent}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Menu, X, Search, User, Moon, Sun, ShieldCheck } from 'lucide-react';
import * as ReactRouterDOM from 'react-router-dom';
import { useLanguage } from '../context/LanguageContext';
import { useTheme } from '../context/ThemeContext';
import { useAdmin } from '../context/AdminContext';
import { CATEGORIES } from '../constants';
import { Container } from './ui/Container';

const { Link, NavLink, useNavigate } = ReactRouterDOM;

export const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchValue, setSearchValue] = useState('');
  const [scrolled, setScrolled] = useState(false);
  const navigate = useNavigate();
  const { t, language, setLanguage } = useLanguage();
  const { theme, toggleTheme } = useTheme();
  const { isAuthenticated } = useAdmin();

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Close mobile menu on ESC
  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setIsOpen(false);
    };
    window.addEventListener('keydown', handleEsc);
    return () => window.removeEventListener('keydown', handleEsc);
  }, []);

  // Lock body scroll when menu is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (searchValue.trim()) {
      navigate(`/search?q=${encodeURIComponent(searchValue)}`);
      setIsOpen(false);
    }
  };

  const handleClearSearch = () => {
    setSearchValue('');
  };

  const handleAdminClick = () => {
    navigate('/admin');
    setIsOpen(false);
  };

  const mainNavItems = [
    { label: t('nav_home'), path: '/', type: 'link' },
    ...CATEGORIES.map(cat => ({
       label: cat.label,
       path: `/${cat.slug}`, 
       type: 'category'
    })),
    { label: t('nav_video'), path: '/video', type: 'link' }
  ];

  return (
    <nav 
      className={`sticky top-0 z-50 w-full transition-all duration-300 ${
        scrolled 
          ? 'bg-white/90 dark:bg-slate-950/80 backdrop-blur-md shadow-sm border-b border-slate-200/80 dark:border-white/5' 
          : 'bg-white/95 dark:bg-slate-950/95 backdrop-blur-sm border-b border-transparent dark:border-white/5'
      }`}
    >
      <div className="relative z-10">
        {/* ROW 1: Brand, Search, Utilities */}
        <Container>
          <div className="flex h-16 items-center justify-between gap-6">

            {/* Logo */}
            <Link to="/" className="flex-shrink-0 flex items-center gap-2 group">
              <span className="font-bold text-xl md:text-2xl tracking-tight text-gradient transition-all duration-300 group-hover:opacity-90">
                Channel Mongolia
              </span>
            </Link>

            {/* Search Bar (Desktop) - QUIET UI & FIXED ALIGNMENT */}
            <div className="hidden md:flex flex-1 max-w-sm mx-auto items-center">
              <form onSubmit={handleSearch} className="w-full relative group">
                  <div className="relative flex items-center">
                    <Search 
                      size={16} 
                      className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" 
                    />
                    <input 
                      type="text" 
                      value={searchValue}
                      onChange={(e) => setSearchValue(e.target.value)}
                      placeholder={t('search_placeholder')}
                      className="w-full h-10 pl-9 pr-9 text-sm rounded-lg
                      bg-slate-100/60 dark:bg-white/5 
                      border border-slate-200 dark:border-white/10
                      text-slate-700 dark:text-slate-200 
                      placeholder-slate-400 dark:placeholder-slate-500
                      focus:outline-none focus:bg-white dark:focus:bg-slate-900 
                      focus:border-brand-purple/50 focus:ring-2 focus:ring-brand-purple/20 
                      transition-all duration-200 ease-out"
                      aria-label="Search"
                    />
                    {searchValue && (
                      <button
                        type="button"
                        onClick={handleClearSearch}
                        className="absolute right-2 top-1/2 -translate-y-1/2 p-1 rounded-full text-slate-400 hover:text-slate-600 dark:hover:text-slate-300 hover:bg-slate-200 dark:hover:bg-white/10 transition-colors"
                        aria-label="Clear search"
                      >
                        <X size={14} />
                      </button>
                    )}
                  </div>
              </form>
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 md:gap-3">
              {/* Language */}
              <button 
                onClick={() => setLanguage(language === 'mn' ? 'en' : 'mn')}
                className="hidden sm:flex items-center gap-1 text-xs font-bold px-3 py-1.5 rounded-full hover:bg-surfaceHighlight transition-colors text-text-muted hover:text-text-main"
              >
                <span className={language === 'mn' ? 'text-brand-purple' : ''}>MN</span>
                <span className="opacity-30 mx-1">/</span>
                <span className={language === 'en' ? 'text-brand-purple' : ''}>EN</span>
              </button>

              {/* Theme Toggle (Desktop) */}
              <button
                onClick={toggleTheme}
                className="p-2 rounded-full text-text-muted hover:bg-surfaceHighlight hover:text-brand-orange transition-colors"
                aria-label={theme === 'dark' ? t('theme_light') : t('theme_dark')}
              >
                {theme === 'dark' ? <Sun size={20} /> : <Moon size={20} />}
              </button>

              {/* Admin */}
              <button 
                onClick={handleAdminClick}
                className={`hidden md:flex items-center gap-2 px-4 py-2 rounded-full text-sm font-semibold transition-all hover:-translate-y-0.5 ${
